// Üretilen dosya: tool/ozgun/uret.py. Tarih · Osmanlı kültür ve kurumları: saray, ordu, ilmiye, vakıflar, gündelik hayat (orta).
const ozHistory13Orta = <(String, String, List<String>, String)>[
  ('Bir tarihçi, padişahın bazı yabancı elçileri kabul ettiği, tahtın bulunduğu ve Enderun\'daki üçüncü avluda yer alan salonu inceliyor. Bu mekân hangisidir?', 'Arz Odası', ['Hazine Koğuşu', 'Sünnet Odası', 'Mermer Teras'], 'Arz Odası, Bâbüssaâde\'nin hemen arkasındaki üçüncü avluda yer alır; padişah burada vezirleri, elçileri ve arz toplantılarını kabul ederdi.'),
  ('Osmanlı Haremi\'nde bir cariyenin padişahla evlenmeden "ikbal" konumuna gelmesi neden toplumsal hareketlilik örneği sayılır?', 'Köle kökenli bir kadının, ilgiyle saray içinde nüfuz ve gelir sahibi olabilmesini gösterdiği için', ['Cariyelerin imtihan sonucuna göre kademe kademe görev ve maaş aldıklarını ve herkesin eşit sayıldığını gösterdiği için', 'Gayrimüslim kadınların haremden dışlandığını gösterdiği için', 'Padişahların tek eşli olduğunu kanıtladığı için'], 'Harem sıkı bir hiyerarşi içeriyordu; cariye kökenli kadınlar padişahın ilgisini kazanarak haseki ya da valide olabilir, bu da yükselme imkânı sağlardı.'),
  ('19. yüzyılda padişahın nikâhlı eşleri için birinci, ikinci gibi sıralamayla kullanılan ve "efendi" sözcüğü içeren unvan hangisidir?', 'Kadınefendi', ['Sultanefendi', 'Hanımsultan', 'Kalfaefendi'], '19. yüzyılda padişahın nikâhlı eşleri birinci, ikinci kadınefendi biçiminde anılırdı.'),
  ('II. Abdülhamid\'in Yıldız Sarayı\'nda boş vakitlerinde uğraştığı, ürünleri arasında mobilyalar da bulunan el sanatı hangisidir?', 'Marangozluk', ['Dokumacılık', 'Ciltçilik ve çinicilik', 'Demircilik'], 'II. Abdülhamid marangozluğa meraklıydı; Yıldız\'daki atölyesinde kendi yaptığı eserler günümüze ulaşmıştır.'),
  ('Yeniçeri ortaları arasında zağarcı, samsuncu ve turnacı gibi adlar taşıyan birlikler hangi uğraşın izini taşır?', 'Av köpekleri ve av kuşlarının yetiştirilmesi', ['Gemi yapımı', 'Barut imalatı, top dökümü ve cephane taşımacılığı', 'Ticaret kervanlarının korunması'], 'Zağar ve samsun av köpeği cinsleri, turna ise av kuşudur; bu adlar ocağın saray avcılığıyla bağlantısına işaret eder.'),
  ('II. Mahmud\'un Haziran 1826\'da kurmak istediği Eşkinci Ocağı\'nın yeniçeriler tarafından tepkiyle karşılanması neden ocağın sonunu hazırlamıştır?', 'Yeniçeriler bunu ocağın sonunun başlangıcı sayıp isyan etti, isyan bastırılınca ocak kaldırıldı', ['Eşkincilerin maaşlarının yeniçerilerden yüksek tutulması yeniçerilerin hoşnutsuzluğuna neden oldu', 'Eşkinci kurulması padişahın tahttan indirilmesiyle sonuçlandı ve ocak kendiliğinden dağıldı', 'Eşkincilerin yalnızca Rumeli\'deki gayrimüslimlerden toplanması yeniçerileri tepkiye sürükledi'], 'Eşkinci Ocağı yeniçerilerden seçilen askerlerden Avrupa usulü eğitimli birlik kurmaktı. Yeniçeriler isyan etti; Vaka-i Hayriye ile ocak kaldırıldı.'),
  ('Ders kitabı kuralına göre her 3000 akçelik gelire karşılık bir cebelü besleyen bir tımar sahibinin geliri 9000 akçe ise kaç cebelü ile sefere katılır?', '3', ['1', '9', '27'], 'Her 3000 akçelik gelire bir cebelü düşer; 9000/3000 = 3 cebelü ile sefere katılır.'),
  ('Sancakbeyine bağlı olarak sancaktaki tımarlı sipahileri yoklama ve sefere hazırlama işlerinde görev alan makam hangisidir?', 'Alaybeyi', ['Sipahi Kethüdası', 'Subaşı', 'Mirlivâ'], 'Alaybeyi, sancakbeyinin vekili olarak sipahileri yoklamaya toplar, seferde onlara komuta ederdi.'),
  ('Osmanlı ordusunda seferde padişahın kurduğu büyük çadıra ne ad verilirdi?', 'Otağ-ı Hümâyûn', ['Serasker Çadırı', 'Kasr-ı Adalet', 'Mehterhane'], 'Padişahın sefer çadırı Otağ-ı Hümâyûn olarak adlandırılırdı. Ordunun merkezindeydi ve törensel işlevi vardı.'),
  ('Osmanlı ordusunda 16. yüzyılın sonlarından itibaren ateşli silah kullanan "sekban" ve "sarıca" adlı birlikler yaygınlaşmıştır. Bunun temel nedeni neydi?', 'Tüfekli piyadenin savaşlardaki üstünlüğünün artması ve tımarlı sipahinin önemini yitirmesi', ['Gayrimüslimlerin orduya alınması ve donanmanın askerî ve mali yönden kıyı halkına bağımlı hale gelmesi', 'Devşirmenin yeniden başlaması', 'Donanmanın yetersiz kalması'], 'Ateşli silahlı piyade ihtiyacı arttıkça merkez, paralı sekban ve sarıca topluluklarını kullandı. Savaş bitince işsiz kalan bu askerler sorun çıkardı.'),
  ('Osmanlı\'da bedel-i nakdî uygulamasının temel anlamı nedir?', 'Belirlenen ücreti ödeyenin askerlik yapmaktan muaf tutulması', ['Gayrimüslimlere zorunlu askerlik uygulanması ve ücretsiz silah dağıtılması hükmü', 'Askerlerin ücretlerinin nakit ödenmesi', 'Seferde ganimetin paylaştırılması'], 'Bedel-i nakdî, askerlik çağındaki kişinin belirli bir bedeli ödeyerek hizmetten kurtulması anlamına geliyordu.'),
  ('1834\'te kurulan Redif Teşkilatı\'nın orduya sağladığı temel yarar nedir?', 'Terhis olan askerlerden oluşan yedek (ihtiyat) kuvvet', ['Donanmaya gönüllü alınan denizcilere ücret ve emeklilik hakkı sağlama sistemi', 'Ücretli yabancı subay sağlanması', 'Devşirme usulüyle asker toplanması'], 'Redif, ordu görevini tamamlayanların yedeğe alınarak gerektiğinde silah altına çağrılması ilkesine dayanan ihtiyat örgütüdür.'),
  ('Osmanlı Devleti\'nde 19. yüzyılda askerlik hizmetini düzenleyen ve kura çekimini getiren sistem hangisidir?', 'Kur\'a usulü', ['Devşirme usulü', 'Pençik', 'Ulufe'], '19. yüzyılda genel askerlik için kur\'a usulü benimsenmiş, devşirme ve pençik gibi yöntemler terk edilmiştir.'),
  ('II. Mahmud\'un yeni ordu için fes, ceket ve pantolon gibi Avrupa tarzı kıyafetleri zorunlu kılması neyi gösterir?', 'Sadece teknik değil, simgesel ve kültürel bir modernleşme çabasını', ['Dinî kıyafetlerin tamamen yasaklandığını ve herkesin aynı giyinmesi zorunluluğunu', 'Gayrimüslimlerin orduya alındığını', 'Yabancı ordulara teslimiyeti'], 'Yeni ordunun kıyafetinin Avrupa tarzına çevrilmesi, askeri yeniliğin görünür simgesi olarak eski düzenden kopuşu vurguluyordu.'),
  ('Kanuni döneminde yapılan Süleymaniye Külliyesi\'ne bağlı medreseler, medrese basamakları içinde hangi konumu kazanmıştır?', 'Sahn-ı Semân\'ın üzerinde en yüksek öğretim basamağı', ['Yalnızca ilkokul düzeyindeki çocuklara ayrılmış başlangıç basamağı', 'Yalnız kızlara ayrılmış basamak', 'Yalnız tıp eğitimine ayrılmış basamak'], 'Süleymaniye medreseleri Fatih\'in Sahn-ı Semân medreselerinin de üstünde, ilmiye yükselişinde en üst basamak sayılmıştır.'),
  ('Bir müderris, cami çevresinde herkese açık dersler verip tefsir ve hadis okutuyor. Bu müderris hangi unvanı taşır?', 'Dersiâm', ['Muîd', 'Müezzinbaşı', 'Nâib'], 'Dersiâm, camilerde halka dersler veren müderrisi anlatır. Muîd ise müderrisin yardımcısı olarak ders tekrarı yapan kişidir.'),
  ('Süleymaniye Külliyesi\'nde hadis ilmi eğitimi için ayrılmış özel yüksek medrese hangisidir?', 'Dârülhadis', ['Dârülkurrâ', 'Dârülfünun', 'Dârüşşifa'], 'Süleymaniye Külliyesi\'nde Dârülhadis, hadis ilmi üzerine uzmanlaşma öğretimi veren bir medrese olarak kurulmuştur.'),
  ('Divan-ı Hümayun\'da sıralama yapılırken Anadolu ve Rumeli kazaskerlerinden hangisi daha üst konumdaydı?', 'Rumeli kazaskeri', ['Anadolu kazaskeri', 'İkisi eşitti', 'Bağdat kazaskeri'], 'Rumeli kazaskeri, Osmanlı\'nın merkezî toprakları Rumeli sayıldığı için Anadolu kazaskerine göre daha üst makam sayılırdı.'),
  ('Yavuz Sultan Selim döneminde şeyhülislamlık yapan ve sade yaşamı ile adaleti savunmasıyla tanınan bilgin kimdir?', 'Zenbilli Ali Cemâlî Efendi (şeyhülislam)', ['Ebussuud Efendi (Kanuni ve II. Selim şeyhülislamı)', 'Kemalpaşazade', 'Molla Gürânî'], 'Zenbilli Ali Cemâlî Efendi, Yavuz Sultan Selim döneminin ünlü şeyhülislamıdır; adaleti ve sadeliğiyle tanınmıştır.'),
  ('Bir müftü, bir fetva sorusunu şeyhülislamlığın resmî dairesine iletecektir. Bu daire hangisidir?', 'Bâb-ı Meşîhat', ['Bâb-ı Âli', 'Bâb-ı Defterdârî', 'Bâb-ı Hümâyûn'], 'Şeyhülislamın makamı ve fetvahane Bâb-ı Meşîhat olarak adlandırılırdı. Bâb-ı Âli ise sadrazamın dairesiydi.'),
  ('Osmanlı\'da bir padişahın tahttan indirilmesinde şeyhülislamın fetvasının aranması neyi gösterir?', 'Yönetimde şer\'i meşruiyetin dayanağı olarak din bilginlerinin onayının gerekli görüldüğünü', ['Padişah yetkilerinin kayıtsız şartsız olduğunu ve din adamlarının siyasete hiç karışmadığını', 'Askerlerin yönetime karışmadığını', 'Meclis-i Mebusan\'ın tek karar organı olduğunu'], 'Tahttan indirmelerde şeyhülislam fetvası hükmün dinî meşruiyetini sağlamak için alınırdı; örneğin 1876 ve 1909\'da böyle yapıldı.'),
  ('Ayasofya Camii\'ndeki büyük duvar levhalarını 19. yüzyılda yazan Osmanlı hattatı kimdir?', 'Kazasker Mustafa İzzet Efendi (hattat)', ['Şeyh Hamdullah', 'Mahmud Celâleddin Efendi (19. yüzyıl hattatı)', 'Mehmed Râkım'], 'Ayasofya\'daki dev yuvarlak levhalar 1840\'lardaki onarım sırasında Kazasker Mustafa İzzet Efendi tarafından yazılmıştır.'),
  ('Sadrazam bir konuyu özetleyerek padişaha rapor sunuyor. Bu rapora ne ad verilir?', 'Telhis', ['Tezkire', 'Berat', 'Muhtıra'], 'Telhis, sadrazamın padişaha sunduğu özet rapordur; padişah bu rapor üzerine hatt-ı hümâyûn ile hüküm yazardı.'),
  ('Osmanlı maliyesinde günlük gelir ve giderlerin kaydedildiği defterlere ne ad verilirdi?', 'Ruznamçe', ['Mühimme-i Hümâyûn', 'Şikâyet', 'Tereke'], 'Ruznamçe, gün gün tutulan gelir gider defteridir; hazinenin akışını gösterir ve bütçe benzeri kayıt olarak kullanılırdı.'),
  ('Osmanlı tuğrasında padişahın adı ve babasının adı ile birlikte yer alan "el-muzaffer daima" ifadesi neyi dile getirir?', 'Padişahın daima zaferle anılması dileğini', ['Seferin başlayacağı tarihi ve ordunun toplanma yerini göstermesini', 'Tahta çıkış yılını', 'Vezirin adını'], 'Tuğra padişahın adı, babasının adı, unvanı ve "el-muzaffer daima" (daima muzaffer olan) ibaresini içerir.'),
  ('Osmanlı\'da para (nakit) vakıflarının işleyişi nasıl gerçekleşirdi?', 'Vakfedilen paranın ihtiyaç sahiplerine borç verilip getirisinin hayra harcanması', ['Paranın hazineye devredilip devlet harcamaları ve ordu masrafları için kullanılması', 'Paranın yatırılıp hiç kullanılmaması', 'Paranın yalnızca yoksullara dağıtılıp bitirilmesi'], 'Para vakıflarında anapara borç olarak verilir, getirisi vakıf amaçlarına harcanırdı. Faiz tartışmaları nedeniyle bu uygulama tartışma konusu olmuştur.'),
  ('Bir vakıf mülkü, peşin yüksek bedel ve yıllık düşük kira karşılığında uzun süreli kiralanıyor. Bu uygulama hangisidir?', 'İcâreteyn', ['Mukataa sistemi', 'İltizam', 'Gedik'], 'İcâreteyn ("iki kira") sistemi, vakıf mülkünü uzun süreli kullanım hakkı karşılığında peşin bir bedel ve yıllık kiraya bağlıyordu.'),
  ('Bir yoksul, cami avlusundaki bir taştan kimseyle yüz yüze gelmeden yardım alıyor. Bu taş hangisidir?', 'Sadaka taşı', ['Sınır (hudut) taşı', 'Mil taşı', 'Mezar taşı'], 'Sadaka taşına para bırakılır, ihtiyaç sahibi alırdı; böylece verenin onuru ve alanın haysiyeti korunurdu.'),
  ('Osmanlı camilerinin dış duvarlarında ve avlularında görülen, kuşlar için yapılmış minyatür köşklere ne ad verilir?', 'Kuş evleri', ['Güvercinlikler ve kümesler', 'Kandil çeşmeleri', 'Şadırvanlar'], 'Kuş evleri çoğu zaman vakıfların desteğiyle yapılan, hayvanları koruma anlayışını gösteren mimari ögelerdi.'),
  ('II. Mahmud\'un vakıfları tek merkezde toplamaya çalışması hangi mali sonucu hedefliyordu?', 'Büyük vakıf gelirleri üzerinde devlet denetimi sağlayıp hazineye kaynak yaratmak', ['Vakıfları tamamen kaldırıp tüm mal varlığını yabancı devletlere ve bankerlere devretmek istemesi', 'Vakıf mallarını yabancı devletlere vermek', 'Vakıfları yalnız gayrimüslimlere bırakmak'], 'Yeni ordu ve yeniliklerin finansmanı için güçlü merkezî yapılanma gerekiyordu; Evkaf Nezareti vakıf gelirlerini denetim altına almayı amaçladı.'),
  ('Devlet, sikkelerdeki gümüş oranını düşürerek para basıyor. Bu uygulama nasıl adlandırılır?', 'Tağşiş', ['Narh', 'Müsadere', 'İltizam'], 'Tağşiş, madeni paradaki saf maden oranının düşürülmesidir; devlet kısa vadeli gelir elde ederken enflasyon ve isyan riskini artırırdı.'),
  ('Osmanlı\'da Fatih döneminde basılmaya başlanan ve altın paranın adı olan sikke hangisidir?', 'Sultani (Altın)', ['Kuruş (gümüş sikke)', 'Mecidiye', 'Beşlik'], 'Altın sikke Osmanlı\'da sultani adıyla anılırdı; akçe ise gümüş esaslı temel para birimiydi.'),
  ('Osmanlı\'da 1881\'de çıkarılan Muharrem Kararnamesi neyi düzenlemiştir?', 'Dış borçların ödenmesi için Düyun-ı Umumiye İdaresi\'nin kurulması', ['Eğitimin zorunlu hale getirilmesi ve ilköğretimin parasız olması için bütçe ayrılması', 'Kapitülasyonların kaldırılması', 'Meclis-i Mebusan\'ın açılması'], 'Muharrem Kararnamesi, alacaklı devletlerle borçların düzenlenmesini ve gelirlerin Düyun-ı Umumiye idaresine devredilmesini sağlamıştır.'),
  ('Yozgat çevresinde güçlenen, Osmanlı\'da ayanlık yaparak yarı bağımsız bir konuma gelen aile hangisidir?', 'Çapanoğulları', ['Karaosmanoğulları', 'Canikli Ali Paşa ailesi', 'Kozanoğulları'], 'Çapanoğulları Yozgat merkezli güçlü bir ayan ailesiydi. Karaosmanoğulları ise Manisa merkezliydi.'),
  ('18. yüzyılda Ege bölgesinde, Manisa merkezli olarak yarı bağımsız bir idare kuran ayan ailesi hangisidir?', 'Karaosmanoğulları', ['Çapanoğulları', 'Cânikli Hacı Ali Paşa ailesi', 'Dülkadiroğulları'], 'Karaosmanoğulları, Manisa ve çevresinde güçlenmiş ve merkezî yönetimle ilişkilerini kendi çıkarlarına göre belirlemiş ayan ailesidir.'),
  ('Taşra ayanlarının 18. yüzyılda güçlenmesinin ardındaki temel sebep nedir?', 'Merkezî otoritenin zayıflaması ve vergi toplama işlerinin yerel güç sahiplerine bırakılması', ['Tımar sisteminin güçlenmesi, merkezî ordunun taşrada etkisini artırması ve ayanların ortadan kalkması', 'Devşirmenin artması', 'Medreselerin kapatılması'], 'Merkez vergi toplamak ve asayişi sağlamak için yerel ayanlara başvurunca ayanlar mali ve askerî güç kazandı.'),
  ('Bir vali, kendi adına bir kazayı yönetmesi için vekil görevlendiriyor. Bu vekile ne denir?', 'Mütesellim', ['Alaybeyi', 'Kethüda', 'Nakîb'], 'Mütesellim, vali veya sancakbeyi adına bir kaza ya da sancağı yöneten vekildi; zamanla bu görev ayan ailelerince de elde edilmiştir.'),
  ('1864 Vilayet Nizamnamesi ile vilayetin alt idari kademeleri hangi sıralamayla oluşturulmuştur?', 'Vilayet, sancak, kaza, nahiye, köy', ['Eyalet, sancak, kaza, vilayet, nahiye, köy', 'Kaza, sancak, nahiye, köy', 'Vilayet, kaza, sancak, köy'], 'Yeni sistemde vilayet, sancak (livâ), kaza, nahiye ve köy sıralaması benimsenmiştir.'),
  ('Osmanlı\'da 1829\'da mahallelerde görevlendirilmeye başlanan yeni yönetici hangisidir?', 'Muhtar', ['Kethüda', 'Çavuş', 'Kâtip'], 'II. Mahmud döneminde mahalle ve köylerde halkla devlet arasında bağ kurmak üzere muhtarlık kurumu başlatılmıştır.'),
  ('İstanbul\'da modern belediyecilik anlayışıyla 1855\'te kurulan kuruma ne ad verilmiştir?', 'Şehremaneti', ['Zaptiye Nezareti', 'Evkâf Nezareti', 'Sur Emaneti'], 'Osmanlı\'da modern belediyecilik 1855\'te İstanbul Şehremaneti\'nin kurulmasıyla başlamış, başında şehremini bulunmuştur.'),
  ('Osmanlı yönetiminin zaman zaman kahvehaneleri kapatmasının en önemli sebebi neydi?', 'Buralarda devlet yönetimi hakkında konuşulması ve toplumsal muhalefetin oluşabilmesi', ['Kahve ithalatının devlet tekelinde olması ve kaçak kahve satışının vergi gelirini azaltması', 'Yeniçerilerin burada kışlalarını kurması', 'Ramazan\'da açık olmaları'], 'Kahvehanelerde siyasi sohbetler ve eleştiriler yapıldığı için yönetim bunları potansiyel muhalefet ve isyan merkezi olarak görmüştür.'),
  ('Klasik Osmanlı toplumunda sarık, kavuk ve ayakkabı renklerinin dine ve görev sınıfına göre farklılaşması neyi gösterir?', 'Toplumsal sınıf ve cemaat farklarının kıyafetle görünür kılındığını', ['Herkesin eşit giyindiğini ve cemaat farklarının kıyafetle tamamen ortadan kaldırıldığını', 'Yalnızca moda anlayışını', 'Giyimin devlet tarafından ücretsiz verildiğini'], 'Kıyafet kuralları devlet görevlisi, esnaf ve gayrimüslim cemaatlerin ayırt edilmesini sağlıyor, toplumsal hiyerarşinin görünürlüğünü artırıyordu.'),
  ('Bir saray aşçısı şerbet, macun ve tatlı yapacaktır. Saray mutfağının hangi bölümünde çalışması gerekir?', 'Helvahane', ['Kilar', 'Kuşhane', 'Dârüzziyafe'], 'Helvahane, helva, macun ve şerbetler gibi tatlıların hazırlandığı saray mutfağı bölümüydü.'),
  ('Okmeydanı\'nda bir okçu rekor attığı menzili belirtmek istiyor. Bu menzili gösteren dikili taşa ne ad verilir?', 'Menzil taşı (okçuluk anıt taşı)', ['Mil taşı (yolcuya mesafe gösteren işaret)', 'Sadaka taşı', 'Kıble taşı'], 'Menzil taşları, okçuların rekor atışlarını ölçmek ve anmak için dikilir; Okmeydanı okçuluk geleneğinin merkeziydi.'),
  ('Bir Osmanlı evinde yatak ve yorganlar gündüz nereye kaldırılarak oda çok amaçlı kullanılırdı?', 'Yüklük', ['Sedir', 'Tandır', 'Gusülhane'], 'Yüklük yatakların gündüz kaldırıldığı dolaptır; bu sayede oda gündüz oturma, gece yatma odası olarak kullanılırdı.'),
  ('Taksim Meydanı\'na adını veren yapı, Osmanlı\'da hangi amaçla yapılmıştır?', 'Suyun şehre dağıtıldığı su bölüştürme (taksim) merkezi', ['Padişahın askerî geçit törenlerini izlediği büyük tören alanı ve karargâhı', 'Yeniçeri kışlası', 'Pazar yeri'], 'Taksim, I. Mahmud döneminde yapılan su bölüştürme (maksem) yapısı nedeniyle bu adı almıştır.'),
  ('Mimar Sinan\'ın hayatını ve eserlerini anlatan Tezkiretü\'l-Bünyan adlı eserin yazarı kimdir?', 'Sâî Mustafa Çelebi (şair ve nakkaş)', ['Evliya Çelebi', 'Kâtip Çelebi (Haccı Halife, bibliyografya yazarı)', 'Mustafa Âli'], 'Tezkiretü\'l-Bünyan, Sinan\'ın çevresindeki şair ve nakkaş Sâî Mustafa Çelebi tarafından Sinan\'ın anlattıklarından yazılmıştır.'),
  ('Bosna\'daki Mostar Köprüsü\'nü 1566\'da hangi mimar yapmıştır?', 'Mimar Hayreddin', ['Mimar Kasım', 'Mimar Mehmed Ağa', 'Mimar Davud Ağa'], 'Mostar Köprüsü, Mimar Sinan\'ın öğrencisi Mimar Hayreddin tarafından yapılmış tek kemerli taş köprüdür.'),
  ('19. yüzyılda Ayasofya\'nın kapsamlı onarımını yapan İsviçreli asıllı mimar kimdir?', 'Gaspare Fossati', ['Alexandre Vallaury', 'Raimondo D\'Aronco', 'Giulio Mongeri'], 'Fossati kardeşler 1847-49 yıllarında Sultan Abdülmecid\'in isteğiyle Ayasofya\'yı onarmış, Mustafa İzzet Efendi\'nin levhaları da o dönemde yazılmıştır.'),
  ('20. yüzyıl başında Vedat Tek ve Mimar Kemaleddin\'in öncülük ettiği Birinci Ulusal Mimarlık Akımı\'nın temel özelliği nedir?', 'Selçuklu ve Osmanlı mimari öğelerini yeniden yorumlamak', ['Tamamen Batı biçimlerini taklit edip yerel geleneklerden kopmak', 'Yalnız beton kullanmak', 'Sadece yapıları sadeleştirmek'], 'Bu akım Selçuklu ve Osmanlı motiflerini modern yapılara taşıyarak milli bir üslup yaratmayı amaçlıyordu.'),
  ('Edirne Selimiye Camii\'nde Mimar Sinan\'ın teknik başarısı olarak gösterilen özellik nedir?', 'Kubbenin sekiz fil ayağına oturtularak geniş ve engelsiz bir iç mekân sağlanması', ['Kubbenin dört fil ayağına oturtulup iç mekânda kalın sütunlarla bölümlendirilmesi', 'Kubbenin tamamen ahşap yapılması', 'Minarelerin kubbeden önce yapılması'], 'Selimiye\'nin kubbesi sekiz ayak üzerine oturtulduğundan iç mekân bütünlüğü ve büyük kubbe etkisi sağlanmıştır.'),
  ('Süleymaniye Camii\'nde kandil isinin toplanması için yapılan ve mürekkep yapımında kullanıldığı söylenen bölüme ne denir?', 'İs odası', ['Hünkâr mahfili', 'Şerefe', 'Kürsü'], 'Kandillerin isini toplayan özel bir bölüm yapıldığı ve is odasında biriken isin mürekkep yapımında kullanıldığı anlatılır.'),
  ('Bir padişah camide cemaatten ayrı ve güvenli bir bölümde namaz kılıyor. Bu bölümün adı nedir?', 'Hünkâr mahfili', ['Minber', 'Mihrap', 'Şadırvan'], 'Hünkâr mahfili padişahın ibadet ederken halktan ayrı ve güvenli durmasını sağlayan özel bölümdür.'),
  ('16. yüzyılın ikinci yarısında İznik çinilerinde ortaya çıkan ve çiniciliğin ünlü rengi sayılan kırmızıya ne denir?', 'Domates kırmızısı', ['Lacivert (kobalt mavisi) çini sırı rengi', 'Turkuaz', 'Sır altı kahverengisi'], 'İznik çinilerinde kabartmalı, parlak domates kırmızısı 16. yüzyılın ikinci yarısında öne çıkmıştır.'),
  ('Hz. Muhammed\'in dış görünüşünü ve ahlâkını anlatan, genellikle yazı ve süsleme ile hazırlanan levha türüne ne denir?', 'Hilye-i şerif', ['Tuğra', 'Murakka', 'Kıt\'a'], 'Hilye-i şerif, Peygamber\'in vasıflarını anlatan metnin sülüs ve nesihle yazılıp süslenmesiyle oluşturulan levhadır.'),
  ('Padişahların hayatı ve başarılarını resimli olarak anlatan, III. Murad döneminde hazırlanan eser hangisidir?', 'Hünernâme', ['Surname', 'Sefaretname', 'Tezkire'], 'Hünernâme, şehnameci Seyyid Lokman\'ın yazdığı ve nakkaş Osman\'ın resimlediği, padişahları anlatan eserdir.'),
  ('17. yüzyılın ünlü bestecisi olan, "Neva Kâr" ve "Tekbir" gibi eserleri bulunan Osmanlı bestekârı kimdir?', 'Itrî', ['Dede Efendi', 'Hâfız Post', 'Zekâî Dede'], 'Itrî, 17. yüzyılın sonu ile 18. yüzyılın başında yaşamış, Nevâ Kâr, Tekbir ve Salât-ı Ümmiye gibi eserleriyle tanınan büyük bestekârdır.'),
  ('II. Mahmud\'un Mehterhane\'nin yerine kurduğu Batı tarzı bandonun başına getirilen İtalyan müzisyen kimdir?', 'Giuseppe Donizetti', ['Callisto Guatelli', 'Tanburi Cemil Bey', 'Hamparsum Limonciyan'], 'Donizetti Paşa 1828\'de Mızıka-yı Hümâyûn\'un başına getirilmiş ve Osmanlı\'da Batı müziğinin kurumlaşmasında önemli rol oynamıştır.'),
  ('Osmanlı klasik müziğinde fasılın başında çalınan enstrümantal eserlere ne ad verilir?', 'Peşrev', ['Semai', 'Saz semaisi', 'Şarkı'], 'Fasıl genellikle peşrevle başlar, taksim, güfteli eserler ve saz semaisiyle sürer. Peşrev, fasılın giriş bölümüdür.'),
  ('Bir bestekâr, eserin zaman düzenini belirleyen vuruş kalıbını seçiyor. Bu kalıba ne denir?', 'Usul', ['Makam', 'Perde', 'Güfte'], 'Usul, bir müziğin zaman düzenini belirleyen vuruş kalıplarıdır; makam ise melodik yapıyı belirler.'),
  ('1917\'de İstanbul\'da kurulan ve Osmanlı\'nın ilk konservatuvarı sayılan müzik okulu hangisidir?', 'Darülelhan', ['Darüşşafaka', 'Darülfünun', 'Mızıka-yı Hümâyûn'], 'Darülelhan, 1917\'de müzik eğitimi vermek üzere kurulmuş ve sonradan İstanbul Konservatuvarı\'na dönüşmüştür.'),
  ('Osmanlı\'da ilk posta pulu hangi yıl kullanılmıştır?', '1863 (ilk pul yılı)', ['1840 (Posta Nezareti yılı)', '1876', '1908'], 'Osmanlı posta pulu 1863\'te kullanıma girmiştir; posta örgütü ise 1840\'ta kurulmuştu.'),
  ('Yeni Osmanlıların 1868\'de Londra\'da çıkardığı, hükûmeti eleştiren gazete hangisidir?', 'Hürriyet', ['Tercüman-ı Ahval', 'Tasvir-i Efkâr', 'İbret'], 'Yeni Osmanlılar, Namık Kemal ve arkadaşlarının yurt dışında çıkardığı Hürriyet gazetesiyle meşrutiyet fikrini yaydı.'),
  ('II. Abdülhamid\'in tahta çıkışının 25. yılı anısına İstanbul\'da ve taşrada yaptırılan yapı türü hangisidir?', 'Saat kulesi', ['Hamam', 'Medrese binası', 'Kervansaray'], 'II. Abdülhamid döneminde 1900-1901\'de tahtta 25. yıl anısına İzmir, Yıldız gibi birçok kentte saat kuleleri yapılmıştır.'),
  ('Osmanlı\'da Şinasi\'nin 1859\'da yazdığı Şair Evlenmesi hangi alanda ilk örnek sayılır?', 'Türk tiyatrosunda yazılmış ilk oyun', ['Türk romanında yazılmış ilk eser ve hikâye', 'Türk gazetesi', 'Türk marşı'], 'Şair Evlenmesi, Batı etkisiyle yazılmış ilk Türkçe tiyatro oyunu olarak kabul edilir.'),
  ('Osman Hamdi Bey\'in 1906 tarihli ünlü tablosu hangisidir?', 'Kaplumbağa Terbiyecisi (Osman Hamdi)', ['Şair Evlenmesi (Şinasi\'nin tiyatro eseri)', 'Bahçedeki Kadın', 'Hamam Sahnesi'], 'Osman Hamdi Bey\'in Kaplumbağa Terbiyecisi, Osmanlı resminin en bilinen eserlerinden biridir ve toplumsal eleştiri içerir.'),
  ('Bir loncada esnaf, devletle ilişkileri yürütecek ve loncanın başında olacak bir kişi seçiyor. Bu kişi hangi unvanı taşır?', 'Kethüda', ['Muhtesib', 'Mütevelli', 'Subaşı'], 'Lonca kethüdası esnafın başkanıydı, esnafın devletle ilişkilerini düzenler ve loncanın iç işleyişini yürütürdü.'),
  ('Bir esnafın eksik tartı kullandığı anlaşılıyor. Çarşıda bu denetimi yapacak belediye görevlisi kimdir?', 'Muhtesib (İhtisab Ağası)', ['Kassam (miras bölüştüren)', 'Çeribaşı', 'Hekimbaşı'], 'Muhtesib, kadının yetkisi altında çarşı denetimi yapar, hileli ölçü ve narh ihlallerini takip ederdi.'),
  ('Eminönü\'ndeki Mısır Çarşısı\'nın İstanbul için temel işlevi neydi?', 'Baharat ve ilaç gibi ürünlerin ticaretini yapıp gelirini Yeni Cami vakfına aktarmak', ['Askerlere silah ve cephane satıp elde edilen geliri Tersane-i Âmire\'ye aktararak donanmayı finanse etmek', 'Yabancı elçilerin ikametini sağlamak', 'Padişah sarayına erzak taşımak'], 'Mısır Çarşısı Yeni Cami Külliyesi\'nin vakıf gelir kaynağıydı; baharat ve ilaç ticaretinin merkeziydi.'),
  ('II. Bayezid\'in 1491\'de Bursa\'da vakıf için yaptırdığı, ipek kozası ticaretinin merkezi olan han hangisidir?', 'Koza Han', ['Vezir Han', 'Emir Han', 'Büyük Han'], 'Koza Han, Bursa\'da ipek kozası alım satımının yapıldığı han olarak ipek ticaretindeki önemi nedeniyle bilinir.'),
  ('Osmanlı çarşılarında aynı mesleğin bir sokakta toplanmasının yönetim açısından temel yararı nedir?', 'Denetimin ve fiyat-kalite kontrolünün kolaylaşması', ['Rekabetin tamamen ortadan kalkıp fiyatların serbest bırakılması', 'Vergilerin kaldırılması', 'Üretimin yurtdışına kayması'], 'Aynı meslek tek yerde toplanınca narh, kalite ve vergi denetimi kolaylaşırdı.'),
  ('Fatih Sultan Mehmed\'in 1454\'te Rum Ortodoks patriği olarak atadığı bilgin kimdir?', 'Gennadios Scholarios (Rum Ortodoks bilgin)', ['Hovakim (Bursa\'dan getirilen Ermeni piskoposu)', 'Mosheh Kapsali', 'Mihail Paleologos'], 'Fatih, fethin ardından Rum Ortodoks cemaatinin başına Gennadios Scholarios\'u getirmiş ve cemaate dinî özerklik tanımıştır.'),
  ('Fatih\'in İstanbul\'da kurulmasını sağladığı Ermeni Patrikhanesi\'nin ilk patriği hangi şehirden getirilen Hovakim\'dir?', 'Bursa', ['Edirne', 'Trabzon', 'Konya'], 'Hovakim, Bursa\'dan İstanbul\'a getirilmiş ve Ermeni Patrikhanesi\'nin ilk patriği olmuştur.'),
  ('Fatih döneminde Osmanlı Yahudi cemaatinin başına getirilen hahambaşı kimdir?', 'Mosheh Kapsali', ['Hovakim', 'Gennadios Scholarios', 'Joseph Nasi'], 'Mosheh Kapsali, Fatih döneminde İstanbul Hahambaşılığı\'na getirilmiş ve Yahudi cemaatinin temsilcisi olmuştur.'),
  ('II. Bayezid\'in 1492\'de İspanya\'dan sürülen Yahudileri Osmanlı topraklarına kabul etmesinin sonucu ne olmuştur?', 'Sefarad Yahudileri Osmanlı\'da yerleşip ticaret ve zanaatta katkı sağlamıştır', ['Osmanlı\'daki Yahudi nüfusu azalmış ve kendi mahallelerinden çıkarılıp sürgün edilmişlerdir', 'Yahudiler Osmanlı\'dan sürülmüştür', 'Yahudilere zorunlu din değiştirme uygulanmıştır'], 'Sefarad Yahudileri Selanik, İstanbul gibi şehirlere yerleşerek ticaret, zanaat ve matbaacılık gibi alanlarda canlılık sağlamıştır.'),
  ('Osmanlı\'da gayrimüslim tüccar ve bankerlerin ticarette öne çıkmasının nedeni neydi?', 'Dış ticaret bağlantıları, dil bilgisi ve kapitülasyonların sağladığı ayrıcalıklar', ['Müslümanların ticaret yapmasının yasak olması ve gayrimüslimlere özel devlet maaşı bağlanması', 'Devletin onlara maaş vermesi', 'Padişahın bütün ticareti onlara bırakması'], 'Dil bilen, Avrupalı ticaret ağlarıyla bağlantılı gayrimüslim tüccarlar kapitülasyon ve berat sistemlerinden yararlanarak öne çıkmıştır.'),
  ('Fatih\'in annesi olarak anılan ve Bursa\'daki Muradiye Külliyesi\'nde türbesi bulunan, II. Murad\'ın eşi olan kadın kimdir?', 'Hüma Hatun', ['Mara Hatun', 'Gülbahar Hatun', 'Mahperi Hatun'], 'Hüma Hatun, II. Murad\'ın eşi ve Fatih\'in annesidir; Bursa\'daki Muradiye Külliyesi\'ndeki türbesi bu sebeple bilinir.'),
  ('Osmanlı\'da kadın yazarların da yazdığı, kadınlara yönelik ilk gazete olarak anılan Hanımlara Mahsus Gazete hangi yılda yayımlanmaya başlamıştır?', '1895 (19. yüzyıl sonu)', ['1860 (Tercüman-ı Ahval yılı)', '1876', '1908'], 'Hanımlara Mahsus Gazete 1895\'te yayımlanmaya başlamış, Osmanlı kadınlarının yazarlık ve okurluk alanındaki ilk büyük kadın gazetesi olmuştur.'),
  ('Osmanlı\'da 1858\'de çıkarılan Ceza Kanunnamesi hangi ülkenin hukukundan esinlenmiştir?', 'Fransa', ['Almanya', 'İngiltere', 'Rusya'], '1858 Ceza Kanunnamesi, Fransız Ceza Kanunu örnek alınarak hazırlanmış ve Tanzimat\'ın hukuk alanındaki Batılılaşma çabalarını yansıtmıştır.'),
  ('Osmanlı\'da 1850\'de çıkarılan Kanun-ı Ticaret hangi alanda yenilik getirmiştir?', 'Fransız Ticaret Kanunu\'ndan esinlenen modern ticaret hukuku', ['Toprak mülkiyeti rejimini ve tapu işlemlerini düzenleyen yeni kanun', 'Vakıf yönetimi', 'Askerlik hizmeti'], '1850 Ticaret Kanunnamesi, Fransız Ticaret Kanunu örnek alınarak hazırlanan modern ticaret hukukunun ilk adımıdır.'),
  ('Osmanlı hukukunda "siyaseten katl" uygulaması neyi ifade eder?', 'Şer\'î delil eksik olsa da toplumsal düzeni korumak için padişahın verdiği idam cezası', ['Kadı mahkemesinin kısas hükmü olarak mağdurun yakınlarına tanıdığı cezalandırma hakkı ve diyet yetkisi', 'Yeniçerilerin kendi aralarında uyguladığı ceza', 'Yabancı konsolosluğun verdiği ceza'], 'Siyaseten katl, devlet düzenini ve genel güvenliği korumak için padişahın yetkisiyle uygulanan, şer\'î deliller aranmayan idamdır.'),
  ('Osmanlı\'da İstanbul\'daki esir pazarının kapatılması hangi padişah döneminde gerçekleşmiştir?', 'Abdülmecid', ['II. Mahmud', 'Abdülaziz', 'II. Abdülhamid'], 'Esir pazarı 1847\'de Abdülmecid döneminde kapatılmış, köle ticareti zamanla sınırlandırılmıştır.'),
  ('Kanuni\'nin sadrazamlarından Lütfi Paşa\'nın vezirlerin nitelikleri ve devlet yönetimi hakkında yazdığı eser hangisidir?', 'Asafname', ['Siyasetname', 'Kutadgu Bilig', 'Ahlâk-ı Alâî'], 'Lütfi Paşa\'nın Asafname\'si, devlet yönetimi, vezirlerin görevleri ve ahlakı konusunda öğüt veren bir siyasetnamedir.'),
  ('Gelibolulu Mustafa Âli\'nin evrensel tarih niteliğindeki eseri hangisidir?', 'Künhü\'l-Ahbâr', ['Tâcü\'t-Tevârih', 'Heşt Behişt', 'Cihannüma'], 'Künhü\'l-Ahbâr, Mustafa Âli tarafından yazılmış, dünya tarihini ve Osmanlı\'nın kuruluşundan itibaren olayları anlatan geniş bir tarih eseridir.'),
  ('II. Bayezid\'in isteği üzerine Âl-i Osman tarihini yazan şeyhülislam kimdir?', 'Kemalpaşazade', ['Ebussuud Efendi', 'Hoca Sâdeddin', 'Âşıkpaşazade'], 'Kemalpaşazade (İbn Kemal), Tevârih-i Âl-i Osman adlı eseriyle Osmanlı\'nın erken dönem tarihini yazmış ve şeyhülislamlık yapmıştır.'),
  ('Kınalızade Ali Çelebi\'nin Ahlâk-ı Alâî adlı eserinde savunduğu "Adalet Çemberi" anlayışına göre devlet nasıl ayakta kalır?', 'Adalet halkı, halk hazineyi, hazine ordu ve devleti güçlü tutar', ['Ordu halkı, halk adaleti, adalet hazineyi, hazine de devleti güçlü tutar', 'Hazine adaleti, adalet ordu, ordu halkı belirler', 'Din bilginleri orduyu, ordu halkı, halk adaleti sağlar'], 'Adalet Çemberi\'nde adalet halkın refahını, refah vergiyi ve hazineyi, hazine orduyu, ordu devleti ayakta tutar.'),
  ('Ahmed Cevdet Paşa\'nın Tarih-i Cevdet adlı eseri hangi dönemi anlatır?', '1774 Küçük Kaynarca\'dan 1826 Yeniçeri Ocağı\'nın kaldırılmasına', ['1299\'dan 1453\'te İstanbul\'un fethine kadar Osmanlı\'nın kuruluş ve yükselme dönemini', '1517\'den 1566\'ya', '1876\'dan 1918\'e'], 'Tarih-i Cevdet, 1774\'ten 1826\'ya kadar Osmanlı tarihini anlatır; Ahmed Cevdet Paşa aynı zamanda Mecelle\'nin başında bulunmuştur.'),
  ('Osmanlı elçilerinin gittikleri ülkeyi ve gözlemlerini anlattıkları rapor veya eserlere ne ad verilir?', 'Sefaretname', ['Nasihatname ve Siyasetname', 'Surname', 'Tezkire'], 'Sefaretnameler, elçilerin gördükleri ülkelerin kurumlarını, gelenek ve yaşam biçimlerini anlattıkları eserlerdir.'),
  ('Mevlevi tarikatına giren bir dervişin tekkede tamamlaması gereken çile süresi kaç gündür?', '1001', ['40 gün', '99', '365'], 'Mevlevi çilesi 1001 gün sürer; dervişin mutfakta, hizmetlerde ve ibadette yetişmesini amaçlar.'),
  ('Ankara\'da Bayramiyye yolunu kuran ve Akşemseddin\'in şeyhi olan mutasavvıf kimdir?', 'Hacı Bayram Veli', ['Hacı Bektaş Veli', 'Yunus Emre', 'Mevlana'], 'Hacı Bayram Veli, Ankara\'da Bayramiyye tarikatını kurmuş; Akşemseddin onun halifelerindendir.'),
  ('Bursa Ulu Camii imamı olan ve Mevlid adlı eseriyle Osmanlı dinî edebiyatının önemli yazarlarından sayılan kişi kimdir?', 'Süleyman Çelebi', ['Yunus Emre', 'Âşık Paşa', 'Fuzuli'], 'Süleyman Çelebi\'nin Vesîletü\'n-Necât (Mevlid) adlı eseri Osmanlı\'da Mevlid geleneğinin başlıca kaynağıdır.'),
  ('Osmanlı\'da tekkelerin toplumsal rolü ibadet ve eğitim dışında nasıl özetlenebilir?', 'Yolcuları konaklatma ve yoksullara yemek verme gibi sosyal hizmet işlevleri', ['Vergi tahsilatı, askerî komutanlık ve eyalet valiliği görevlerini üstlenmek ve yürütmek', 'Yargı kararı alıp infaz etme', 'Devlet defterlerini tutma'], 'Tekkeler gelen geçene aş ve barınak sağlayan, hayır ve hizmet merkezleriydi; bu yönüyle vakıflarla da bağlantılıydı.'),
  ('Yabancı elçilerin padişah huzuruna iki görevli tarafından kollarından tutularak çıkarılmasının temel amacı neydi?', 'Güvenliği sağlamak ve devletin otoritesini sergilemek', ['Elçiyi yorarak görüşme süresini kısaltmak ve kendine ağırlık kazandırmak', 'Elçinin dilini öğretmek', 'Padişaha ücretsiz hediye vermek'], 'Elçinin kollarının tutulması hem olası saldırılara karşı güvenlik önlemi hem de padişah huzurundaki protokolün bir parçasıydı.'),
  ('II. Abdülhamid\'in Yıldız Sarayı bahçesinde Avrupa\'dan usta getirterek kurduğu ve porselen ürettiği kuruluş hangisidir?', 'Yıldız Çini Fabrikası', ['Hereke Fabrikası', 'Feshane', 'Tekfur Sarayı Çini Atölyesi'], 'Yıldız Çini Fabrikası, sarayın ihtiyaçları ve hediyeleşmeler için porselen üretmek amacıyla kurulmuş saray atölyesidir.'),
  ('Osmanlı\'da veraset konusunda I. Ahmed\'den itibaren uygulanan "ekber ve erşed" ilkesi neyi öngörür?', 'Tahta hanedanın en yaşlı ve olgun erkek üyesinin geçmesini', ['Tahta valilik yapmış en deneyimli şehzadenin geçmesini', 'Tahta babanın büyük oğlunun geçmesini', 'Tahta sadrazamın seçtiği kişinin geçmesini'], 'Ekber ve erşed ilkesi, hanedanın en yaşlı ve en olgun üyesinin tahta çıkmasını öngörür; bu uygulama babadan oğula geçişin yerini almıştır.'),
  ('Osmanlı ordusunun 16. yüzyılda Çaldıran ve Mohaç\'ta kullandığı "tabur cengi" taktiğinin esası neydi?', 'Arabaların birbirine bağlanarak oluşturulan korunaklı hat arkasında tüfek ve topla savaşılması', ['Süvari birliklerinin sürekli hücum ederek düşman hattını yarmaya çalışması ve ağır ateşli silah kullanmaması', 'Donanmanın karadan destek vermesi', 'Kalelerin kuşatılıp aç bırakılması'], 'Tabur cengi, arabaların zincirlenip bir savunma hattı oluşturması ve arkasında ateşli silahlı piyadenin ateş açmasıyla uygulanırdı.'),
  ('İstanbul\'daki Tophane semtinin adı hangi kuruluştan gelir?', 'Tophane-i Âmire (top döküm ve silah imalathanesi)', ['Tersane-i Âmire (Haliç\'te gemi yapım ve onarım tersanesi)', 'Baruthane-i Âmire (barut fabrikası)', 'Darphane-i Âmire (para basım evi)'], 'Tophane, Osmanlı\'nın top döküm ve silah üretimi yapılan Tophane-i Âmire\'nin bulunduğu yer olduğundan bu adı almıştır.'),
  ('Yeniçeri Ocağı kaldırıldıktan sonra Yeniçeri Ağası\'nın konağı hangi kuruma dönüştürülmüştür?', 'Seraskerlik (Bâb-ı Seraskerî)', ['Evkâf-ı Hümâyûn Nezareti (vakıf yönetimi)', 'Darülfünun', 'Posta Nezareti'], 'Yeniçeri Ağası\'nın Beyazıt\'taki konağı Seraskerlik makamına tahsis edilmiş, sonraki yıllarda Harbiye Nezareti merkezi olmuştur.'),
  ('II. Mahmud döneminde fes üretimi için 1835\'te İstanbul\'da kurulan fabrika hangisidir?', 'Feshane', ['Hereke', 'Zeytinburnu Demir Fabrikası', 'Beykoz Deri Fabrikası'], 'Feshane, askerî kıyafetin parçası olan feslerin üretimi için Eyüp\'te Haliç kıyısında kurulmuştur.'),
  ('19. yüzyılda Osmanlı\'nın kurduğu fabrikaların çoğu neden kalıcı bir sanayi atılımına dönüşememiştir?', 'Yetersiz sermaye, uzman eksikliği ve Avrupa mallarıyla rekabet gücü zayıflığı nedeniyle', ['Padişahın sanayiyi yasaklaması ve fabrikaların tamamen kapatılması gerekçesiyle iç pazarın daralması nedeniyle', 'Fabrikaların hep yabancılara satılması nedeniyle', 'Hammaddenin tamamen bulunmaması nedeniyle'], 'Fabrikalar çoğunlukla ordunun ihtiyaçlarına yönelikti; sermaye, teknik bilgi ve rekabet güçlükleri sanayileşmeyi sınırlamıştır.'),
  ('III. Selim\'in Nizam-ı Cedid ordusunu kurarken Avrupa\'dan öğretmen, subay ve yeni silah getirtmesi neyi gösterir?', 'Askerî yenilenmenin Batı örneklerine bakılarak yapılmaya başlandığını', ['Osmanlı\'nın orduyu tamamen dağıtıp yalnızca gönüllü milis birliklerine dayanmaya başladığını', 'Yeniçerilerin güçlendiğini', 'Devşirmenin yeniden canlandığını'], 'III. Selim yeni ordu için Fransız ve diğer Avrupalı uzmanlardan yararlanmış, bu Osmanlı\'da Batı örneğiyle askerî modernleşmenin başlangıcıdır.'),
  ('Bir mahallede Kur\'an\'a başlayan çocuk süslü bir alayla dolaştırılıyor. Bu tören nedir?', 'Âmin alayı', ['Surre alayı', 'Kılıç alayı', 'Sünnet alayı'], 'Âmin alayı, sıbyan mektebinde Kur\'an\'a başlayan veya bitiren çocuğun süslü bir alayla dolaştırılıp dualarla uğurlandığı mahalle törenidir.'),
  ('Bir kitapsever, Beyazıt\'ta kitap ve elyazması alıp satmak için nereye gider?', 'Sahaflar Çarşısı', ['Mısır Çarşısı', 'Zindan Han', 'Kapalıçarşı'], 'Sahaflar Çarşısı, İstanbul\'da Beyazıt\'ta bulunan, kitap ve elyazması ticaretiyle bilinen tarihî çarşıdır.'),
  ('II. Mahmud döneminde Takvim-i Vekayi\'nin basıldığı devlet matbaası hangisidir?', 'Matbaa-i Âmire', ['Darphane-i Âmire', 'Tersane-i Âmire', 'Cebehane-i Âmire'], 'Matbaa-i Âmire, 1831\'de Takvim-i Vekayi\'yi basan devlet matbaası olarak resmî yayıncılığın merkezi olmuştur.'),
  ('Osmanlı\'da 1870\'te kız öğretmen yetiştirmek için kurulan okul hangisidir?', 'Darülmuallimat (kız öğretmen okulu)', ['Darülmuallimin (erkek öğretmen okulu)', 'Kız Rüştiyesi', 'Darüşşafaka'], 'Darülmuallimat, ilk kız öğretmen okuludur ve kadınların eğitim alanındaki mesleki yükselişinin önemli adımıdır.'),
  ('Osmanlı mezar taşlarında erkeklerde başlık biçimlerinin ayrı ayrı olmasının nedeni neydir?', 'Kişinin mesleğini, rütbesini ya da toplumsal konumunu belirtmek', ['Ölüm nedenini ve ölenin hangi hastalıktan vefat ettiğini belirtmek', 'Mezarın yönünü belirtmek', 'Kişinin yaşını belirtmek'], 'Mezar taşı başlıkları sarık, kavuk, fes gibi biçimlerle ölenin statüsünü ve görevini simgeler, mezarlıklar toplumsal tarih belgesi gibidir.'),
  ('Osmanlı\'da geleneksel "alaturka saat" sistemine göre gün batımı hangi saati gösterir?', '12', ['6', '24', '0'], 'Alaturka saatte gün batımında saat 12 kabul edilir ve gün oradan itibaren yeniden başlar; bu yüzden saatler sürekli ayarlanırdı.'),
  ('Osmanlı evlerinde yemeklerin üzerine konulup etrafında oturularak yenilen bakır veya ahşap büyük tepsiye ne denirdi?', 'Sini', ['Kazan', 'Tencere', 'Rahle'], 'Sini, yer sofrasının üzerine konulan büyük tepsidir; aile bireyleri etrafına oturup ortak kaptan yemek yerdi.'),
  ('İstanbul\'da 1777\'de kurulan ve lokumuyla ünlenen, Osmanlı sarayına da lokum sağladığı bilinen şeker ustası kimdir?', 'Hacı Bekir', ['Hacı Şükrü', 'Hacı Bayram', 'Hacı Bektaş'], 'Hacı Bekir, İstanbul\'da lokum üretimini ticari bir işe dönüştürmüş ve zamanla sarayın da tedarikçisi olmuştur.'),
  ('Yeni Cami\'nin (Eminönü) temelini 1597\'de atan, III. Mehmed\'in annesi olan valide sultan kimdir?', 'Safiye Sultan', ['Kösem Sultan', 'Nurbanu Sultan', 'Hürrem Sultan'], 'Yeni Cami\'nin inşasına III. Mehmed\'in annesi Safiye Sultan başlamış, cami yarım kalmış ve Turhan Sultan tarafından tamamlanmıştır.'),
  ('Manisa\'da Mesir Macunu geleneğinin başlamasıyla ilişkilendirilen, Kanuni\'nin annesi olan valide sultan kimdir?', 'Hafsa Sultan', ['Nurbanu Sultan', 'Mihrimah Sultan', 'Gülbahar Hatun'], 'Hafsa Sultan, Manisa\'da Merkez Efendi\'nin yaptığı Mesir Macunu ile iyileşmiş; macun dağıtımı Manisa Mesir Şenliği olarak sürmüştür.'),
  ('III. Mehmed\'in 1595\'te tahta çıktığında kaç kardeşini öldürttüğü anlatılır?', '19 şehzade', ['9 şehzade', '5 şehzade', '31 şehzade'], 'III. Mehmed, tahta çıkarken 19 kardeşini idam ettirmiş; bu olay son büyük kardeş katli olarak anılır.'),
  ('Bursa Ulu Camii\'nin yirmi kubbeli olmasının nedeni olarak anlatılan olay nedir?', 'Niğbolu zaferi sonrası yirmi cami yapma adağının tek camide yerine getirilmesi', ['Padişahın yirmi çocuğu olmasının anısına yirmi kubbeli yapılması ve camiye çocuklarının adlarının verilmesi', 'Yirmi tarikatın cami yaptırması', 'Bursa\'da yirmi mahallenin bulunması'], 'Yıldırım Bayezid, Niğbolu zaferi sonrası yirmi cami yapma adağını Ulu Cami\'yi yirmi kubbeli yaparak yerine getirmiştir.'),
  ('Edirne\'deki Üç Şerefeli Cami\'nin adı nereden gelmektedir?', 'Minarelerinden birinin üç şerefeli olmasından', ['Üç farklı mimar tarafından üç ayrı aşamada yapılmış olmasından dolayı', 'Üç padişah döneminde bitmesinden', 'Üç kubbeli olmasından'], 'Üç Şerefeli Cami, üç şerefeli minaresiyle ünlüdür; II. Murad döneminde yapılmış, Osmanlı mimarisinde Bursa\'dan Edirne\'ye geçişin örneğidir.'),
  ('Süleymaniye Camii\'nin dört minaresindeki toplam on şerefe sayısı hangi duruma gönderme yapar?', 'Kanuni\'nin onuncu Osmanlı padişahı olmasına', ['Caminin on yılda tamamlanıp inşaatta on bin işçi çalışmasına', 'Onuncu yüzyıl hicri takvimine', 'Kanuni\'nin on çocuğuna'], 'Süleymaniye\'nin dört minaresinde toplam on şerefe bulunması Kanuni\'nin onuncu padişah olmasıyla ilişkilendirilir.'),
  ('Osmanlı\'da bir camide iki veya daha çok minare bulunmasının geleneksel anlamı nedir?', 'Camiyi padişah veya hanedan üyesinin yaptırmış olması', ['Caminin kentin en eski camisi olması ve yalnızca cuma namazı için açılmış bulunması', 'Caminin yalnız cuma namazı için açılması', 'Caminin bir tekkeye bağlı olması'], 'İki veya daha çok minare selâtin camilerinin (padişah ve hanedan camilerinin) ayrıcalığı sayılır; vezirler ve halk genellikle tek minareli cami yaptırırdı.'),
  ('Bir müezzin ezan okumak için minarenin dışa taşan hangi bölümüne çıkar?', 'Şerefe (minare balkonu)', ['Mahfil (yükseltilmiş loca bölümü)', 'Revak', 'Kürsü'], 'Şerefe, minare gövdesindeki balkondur; Osmanlı\'da şerefe sayısı caminin önemini ve yapıldığı dönemi yansıtabilir.'),
  ('Osmanlı camilerinde ana ibadet mekânının önünde bulunan, sütunlu ve kubbeli geçide ne ad verilir?', 'Son cemaat yeri', ['Hünkâr mahfili', 'Minber', 'Mihrap'], 'Son cemaat yeri, geç gelen cemaatin namaz kıldığı ve girişi karşılayan sütunlu bölümdür; Osmanlı camilerinin tipik özelliklerinden biridir.'),
  ('Sinan\'ın Edirnekapı\'da yaptığı, Mihrimah Sultan adına yapılan camii hangi özellikle bilinir?', 'Çok sayıda pencerenin sağladığı aydınlık iç mekânı ile', ['Altın yaldızlı kubbesi ve çok sayıdaki ince ve yüksek minareleri ile', 'Sekiz minaresi ile', 'Taş oymalı çeşmesi ile'], 'Edirnekapı Mihrimah Sultan Camii, çok sayıdaki penceresi sayesinde Osmanlı camilerinin en aydınlık yapılarından biri sayılır.'),
  ('Osmanlı\'nın Kudüs\'te Kanuni döneminde yaptırdığı ve bugün de ayakta olan yapı grubu hangisidir?', 'Kudüs Surları', ['Selimiye Camii', 'Hamidiye Kulesi', 'Süleymaniye Külliyesi'], 'Kudüs\'ün bugünkü surları Kanuni Sultan Süleyman döneminde 16. yüzyılda yenilenmiştir.'),
  ('İstanbul\'da Galata\'yı Beyoğlu\'na bağlayan ve 1875\'te hizmete giren yeraltı demiryolu hangisidir?', 'Tünel', ['Tramvay', 'Hicaz Hattı', 'Bağdat Demiryolu'], 'Tünel, 1875\'te Galata ile Beyoğlu arasında hizmete açılan, dünyanın en eski yeraltı raylı sistemlerinden biridir.'),
  ('İstanbul\'da 1871\'de ilk kez hizmete giren at arabalı toplu ulaşım türü hangisidir?', 'Atlı tramvay', ['Elektrikli tramvay', 'Vapur', 'Otobüs'], 'İstanbul\'da 1871\'de başlayan atlı tramvay, kent içi toplu taşımacılığın ilk modern biçimidir; elektrikli tramvay sonradan kullanılmıştır.'),
  ('Bir tahrir kâtibi köy köy hane ve kişi adlarını ayrıntılı olarak yazıyor. Bu defter türü nedir?', 'Mufassal defter', ['İcmal defter', 'Ruznamçe', 'Mühimme defteri'], 'Mufassal defterler köy köy hane ve kişi adlarıyla gelir kalemlerini ayrıntılı kaydeder; icmal defterler ise özet niteliğindedir.'),
  ('Evli ama toprağı olmayan bir köylü tahrir defterinde hangi gruba kaydedilir?', 'Caba', ['Mücerred', 'Bennak', 'Çift'], 'Caba, toprağı olmayan evli köylü; bennak, yarım çiftten az toprağa sahip evli köylü; mücerred ise bekâr erkektir.'),
  ('Osmanlı\'da Mısır\'dan her yıl İstanbul\'a gönderilen vergi gelirine ne ad verilirdi?', 'İrsaliye-i Mısır', ['Cizye', 'Haraç', 'Surre'], 'İrsaliye-i Mısır, Mısır eyaletinin yıllık vergi gelirinden merkezî hazineye gönderilen paydır; Mısır\'ın en önemli gelir kaynaklarından biridir.'),
  ('İslam devletlerinde egemenliğin iki temel simgesi olarak görülen uygulamalar hangileridir?', 'Hutbe okutmak ve para (sikke) bastırmak', ['Sefer yapmak ve düzenli olarak vergi toplatmak ile ordu beslemek', 'Medrese kurmak ve kadı atamak', 'Sancak çekmek ve mehter çaldırmak'], 'Hutbede hükümdarın adının anılması ve sikkeye adının basılması egemenliğin göstergesiydi; padişah tahta çıkınca cülus sikkesi bastırırdı.'),
  ('Mecelle-i Ahkâm-ı Adliye kaç maddeden oluşur?', '1851 madde (16 kitap)', ['999 madde', '2020 madde', '365 madde (yılın günleri sayısınca)'], 'Mecelle 1851 maddeden oluşur ve 16 kitap hâlinde düzenlenmiştir; Hanefi fıkhına dayanır.'),
  ('Mecelle\'nin başında yer alan "99 külli kaide" ne işe yarar?', 'Hükümlerin yorumlanmasında kullanılan genel hukuk ilkelerini sunar', ['Yalnızca vergi oranlarını ve devlet gelirlerinin paylaşımını belirleyip kadılara bildirir', 'Padişahın yetkilerini sıralar', 'Kadıların maaşını düzenler'], 'Külli kaideler, tek tek hükümlerin dayandığı genel ilkeleri verir; kadılar ve hukukçular uyuşmazlıkları bu ilkelerle yorumlardı.'),
  ('Bir pazarda mallar açık artırma ile satılıyor ve alıcıyla satıcıyı bir aracı buluşturuyor. Bu aracı kimdir?', 'Dellâl', ['Muhtesib', 'Kassam', 'Bohçacı'], 'Dellâl, pazarda mal ve gayrimenkul satışını açık artırma ile yürüten aracıydı; alıcı ve satıcıyı buluşturur, hizmeti için komisyon alırdı.'),
  ('Osmanlı Devleti\'nde köylerde yaşayan halkın büyük çoğunluğunun temel geçim kaynağı neydi?', 'Tarım ve hayvancılık', ['Dokumacılık ve el sanatları', 'Madencilik', 'Gemicilik'], 'Osmanlı toplumunun çoğunluğu köylerde yaşar, geçimini tarım ve hayvancılıkla sağlardı; vergi gelirlerinin ana kaynağı da buydu.'),
  ('Osmanlı\'nın 16. yüzyılda ipekli dokumalarıyla ünlü, kemha ve atlas üretiminin merkezi olan şehri hangisidir?', 'Bursa', ['Edirne', 'Konya', 'Trabzon'], 'Bursa, Osmanlı\'nın başlıca ipek ticareti ve ipekli kumaş (kemha, atlas) üretimi merkeziydi; saray kumaşlarının önemli bölümü burada dokunurdu.'),
  ('Osmanlı Devleti\'nde Hz. Muhammed\'in soyundan gelenlerin (seyyidlerin) sarık veya başlıklarında hangi rengin kullanılması gelenekti?', 'Yeşil', ['Kırmızı', 'Mor', 'Sarı'], 'Seyyidler sarıklarında yeşil rengi kullanırdı; bu renk İslam\'da Hz. Peygamber\'e bağlı bir simge olarak kabul edilirdi.'),
  ('Topkapı Sarayı Hazinesi\'nde sergilenen, yaklaşık 86 karatlık ünlü elmas hangisidir?', 'Kaşıkçı Elması (Topkapı elması)', ['Koh-i Nur (Hindistan kökenli ünlü elmas)', 'Hope Elması', 'Regent Elması'], 'Kaşıkçı Elması, Topkapı Sarayı Hazine Dairesi\'nde sergilenen, dünyanın en değerli elmaslarından biri sayılan 86 karatlık bir mücevherdir.'),
  ('Topkapı Sarayı Hazinesi\'ndeki ünlü hançerin yapılış amacı, hangi hükümdara hediye edilmek içindi?', 'İran Şahı Nadir Şah', ['Rus Çarı I. Petro', 'Fransa Kralı XV. Louis', 'Hindistan Babür Padişahı'], 'Topkapı Hançeri, Nadir Şah\'a hediye edilmek üzere yapılmış; Nadir Şah\'ın ölümü üzerine elçilik yarıdan geri dönmüştür.'),
  ('16. yüzyılda Osmanlı halıcılığının en önemli merkezi olarak bilinen yer neresidir?', 'Uşak', ['Konya', 'Bursa', 'Trabzon'], 'Uşak, Osmanlı halıcılığının merkezi olarak 16. yüzyılda saray ve ihracat için dokumalar üretmiş; Avrupa\'da da büyük ilgi görmüştür.'),
  ('Hat örneklerinin ve minyatürlerin bir arada ciltlendiği albüme ne ad verilir?', 'Murakka', ['Divan', 'Surname', 'Hünername'], 'Murakka, hattatların yazılarını, bazen resim ve minyatürleri bir araya getiren, saray ve koleksiyoncuların hazırladığı albümdür.'),
  ('Bir nakkaş, kitap sayfasına ince altın tozu serpiyor. Bu tekniğin adı nedir?', 'Zerefşan', ['Ebru', 'Minyatür', 'Kündekâri'], 'Zerefşan, kâğıdın üzerine ince altın tozlarının serpilmesiyle yapılan süsleme tekniğidir; tezhip ve cilt sanatlarında görülür.'),
  ('Bir marangoz, ahşap parçaları çivi ve tutkal kullanmadan geçmeli biçimde birleştiriyor. Bu teknik nedir?', 'Kündekâri', ['Sedef kakma', 'Hatayi', 'Zerefşan'], 'Kündekâri, ahşap parçaların geçmeli birleştirilmesiyle yapılan bir tekniktir; kapı, minber ve mihrap gibi öğelerde görülür.'),
  ('İstanbul\'daki Aksaray ve Karaman semtlerinin adları neyin sonucudur?', 'Fethin ardından bu bölgelerden gelen nüfusun İstanbul\'a yerleştirilmesinin', ['Selçuklu valilerinin bu şehirlerin halkına bu adları vermiş olması ve semtlere vakıf konulması', 'Kervan yollarının İstanbul\'a bağlanmasının', 'Bu şehirlerin İstanbul\'a bağlı olmasının'], 'Aksaray ve Karaman halkı Fatih döneminde İstanbul\'a iskân edilmiş, semtlerine memleketlerinin adı verilmiştir.'),
  ('Osmanlı\'nın bugünkü ay-yıldızlı kırmızı bayrağı resmen hangi yıl kabul edilmiştir?', '1844', ['1453', '1876', '1908'], 'Osmanlı bayrağının ay ve yıldızlı kırmızı biçimi Abdülmecid döneminde 1844\'te resmen düzenlenmiştir.'),
  ('Osmanlı ordusunda seferde askerlerin temel azığı olarak görülen, kurutulmuş ve uzun süre bozulmayan ekmek türü hangisidir?', 'Peksimet (kuru ekmek)', ['Simit (susamlı halka ekmek)', 'Lavaş', 'Pide'], 'Peksimet, uzun süre saklanabildiği için sefer yiyeceği olarak ordu ve donanmada yaygın kullanılırdı.'),
  ('Osmanlı ordusunda seferler için kurulan ordugâhta yiyecek ve erzağın önceden depolandığı mekânlara genel olarak ne denirdi?', 'Menzil ve ambar', ['Bedesten ve kapalı çarşı', 'Tersane', 'Medrese'], 'Sefer güzergâhında menzillerde erzak ve zahire depolanır, ordunun ikmali önceden planlanırdı.'),
  ('Osmanlı\'da 18. yüzyılda yaşayan ve kendi adını taşıyan kütüphaneyi 1762\'de İstanbul\'da yaptıran sadrazam ve şair kimdir?', 'Koca Ragıp Paşa', ['Nevşehirli Damat İbrahim Paşa', 'Sokollu Mehmed Paşa', 'Köprülü Fazıl Ahmed Paşa'], 'Ragıp Paşa Kütüphanesi, müstakil kütüphane yapısına örnek olan 1762 tarihli yapıdır ve devlet adamlarının kültürel himayesini gösterir.'),
  ('"Nizam-ı âlem" anlayışının Osmanlı yönetimindeki işlevi nedir?', 'Toplumun ve devlet düzeninin korunmasını meşrulaştıran temel ilke olması', ['Askerlerin ücretini belirleyip hazineden ödenmesini sağlayan mali kural olması ve padişahın yetkisini kısıtlaması', 'Vakıfların yönetilmesi', 'Yabancı devletlerle ticaret yapılması'], 'Nizam-ı âlem, devletin amacını düzen ve adaleti korumak olarak tanımlar; kardeş katli gibi uygulamaları da bu gerekçeyle savunulmuştur.'),
  ('17. yüzyıl Osmanlı nasihatnamelerinde "kanun-ı kadim" kavramı neyi anlatır?', 'Devletin eski, güçlü dönemindeki kural ve düzenin geri getirilmesi gerektiği anlayışını', ['Yeni Batı kanunlarının alınması ve eski geleneklerin bütünüyle terk edilmesi gerektiği anlayışını', 'Medreselerin kapatılmasını', 'Yabancı elçilere ayrıcalık verilmesini'], 'Nasihatnameler gerileme nedenini eski düzenin bozulmasında görür ve çözümü kanun-ı kadime, yani eski kanun ve geleneğe dönmede arardı.'),
  ('Osmanlı iktisadi zihniyetindeki "iaşecilik" ilkesi neyi öngörür?', 'Halkın ve ordunun ihtiyaç duyduğu malların bol ve ucuz bulunmasının sağlanmasını', ['Hazine gelirinin sürekli artırılması ve ihracatın her türlü mal için özendirilmesi gerektiğini', 'Eski usullerin korunmasını', 'Dış ticaretin tamamen serbest bırakılmasını'], 'İaşecilik, şehir ve ordunun iaşesini sağlamak amacıyla ihracatın kısıtlanması ve fiyatların denetlenmesi anlamına gelir.'),
  ('Osmanlı iktisadi zihniyetindeki "fiskalizm" ilkesi neyi ifade eder?', 'Devlet hazinesinin gelirini artırmayı öncelemeyi', ['Ücretlerin düşürülüp devlet harcamalarının yalnızca askeriyeye yönlendirilmesini', 'Dış ticaretin yasaklanmasını', 'Vergilerin tamamen kaldırılmasını'], 'Fiskalizm, devlet gelirlerinin artırılmasına öncelik veren anlayıştır; gümrük ve vergi politikaları bu amaca göre biçimlenirdi.'),
  ('Osmanlı\'da 18. yüzyılda yayılan "çiftlik" işletmeleri tarım ekonomisinde neyi gösterir?', 'Ayan ve zenginlerin ticari amaçlı büyük toprak işletmeleri kurmasını', ['Köylünün topraksız kalmasını ve devletin tüm toprakları yeniden tımara bağlamasını', 'Tımar sisteminin güçlenmesini', 'Ordu için arazi bölünmesini'], 'Çiftlikler, ayan ve ağaların piyasaya yönelik üretim yaptığı büyük işletmelerdi ve tımarın gerilemesiyle yaygınlaşmıştır.'),
  ('Osmanlı Devleti\'nin 1875\'te dış borçlarının faiz ve anapara ödemesini askıya aldığı karar hangisidir?', 'Ramazan Kararnamesi', ['Muharrem Kararnamesi', 'Tanzimat Fermanı', 'Islahat Fermanı'], '1875\'te ilan edilen Ramazan Kararnamesi moratoryum anlamına gelir ve Osmanlı\'nın mali iflasını gösterir.'),
  ('Divan şairi Şeyh Galib\'in şeyhlik yaptığı Beyoğlu\'ndaki Mevlevi tekkesi hangisidir?', 'Galata Mevlevihanesi', ['Yenikapı Mevlevihanesi', 'Eyüp Mevlevihanesi', 'Bahariye Mevlevihanesi'], 'Şeyh Galib, Hüsn ü Aşk eserinin yazarı olarak, Galata Mevlevihanesi şeyhi olmuştur; tekke bugün müze olarak ziyaret edilir.'),
  ('Osmanlı loncalarında çırağın kalfa ya da ustalığa yükseldiğini topluluk önünde gösteren belirli bir töreni vardı. Bu töre neyi simgelerdi?', 'Şed kuşanma ile esnaf topluluğuna resmen kabul edilmeyi', ['Askerlik hizmetinin tamamlandığını ve ordudan terhis olunduğunu', 'Vergiden muaf olmayı', 'Padişah huzurunda yemin etmeyi'], 'Şed (kuşak) kuşanma, çırağın kalfa ya da usta olarak meslek topluluğuna kabulünü gösteren törendir; hem meslekî hem ahlaki bir geçiş ritüeliydi.'),
  ('Osmanlı kadılarının mahkemelerde karara varmak için başvurduğu temel dinî hukuk ekolü hangisidir?', 'Hanefi fıkhı', ['Şafii fıkhı', 'Maliki fıkhı', 'Hanbeli fıkhı'], 'Osmanlı Devleti\'nde resmî fıkıh mezhebi Hanefi\'dir; kadılar kararlarını bu mezhebe göre verir, çözemedikleri konuda müftüye danışırdı.'),
  ('Osmanlı medreselerinde fıkıh eğitiminde okutulan temel Hanefi eseri hangisidir?', 'Hidâye', ['Mesnevi', 'Siyasetname', 'Tevârih-i Âl-i Osman'], 'Hidâye, Hanefi fıkhının temel kaynaklarından biri olup medreselerde okutulurdu; Mesnevi bir tasavvuf eseridir.'),
  ('Osmanlı\'da bir padişahın seferlerini ve zaferlerini anlatmak için yazılan eserlere ne ad verilir?', 'Gazavatname (sefer anlatısı)', ['Sefaretname (elçinin gözlem raporu)', 'Nasihatname', 'Seyahatname'], 'Gazavatname, padişah veya komutanların savaş ve seferlerini ve kazandıkları zaferleri öven, olayları ayrıntılı anlatan eserdir.'),
  ('Osmanlı şairlerinin hayatını ve örnek şiirlerini bir arada veren eserlere ne ad verilir?', 'Tezkire', ['Salname', 'Hünername', 'Sefaretname'], 'Şuara tezkireleri, şairlerin yaşamlarını ve örnek şiirlerini aktaran eserler olup 16. yüzyılda Latifi, Âşık Çelebi gibi yazarlarla yaygınlaşmıştır.'),
  ('Takvim-i Vekayi (1831), Tercüman-ı Ahval (1860) ve Hürriyet (1868) gazetelerini çıkış sırasına göre dizdiğimizde sıralama nasıl olur?', 'Takvim-i Vekayi, Tercüman-ı Ahval, Hürriyet', ['Hürriyet, Takvim-i Vekayi, Tercüman-ı Ahval sırasıyla', 'Tercüman-ı Ahval, Hürriyet, Takvim-i Vekayi', 'Takvim-i Vekayi, Hürriyet, Tercüman-ı Ahval'], 'Resmî gazete Takvim-i Vekayi 1831\'de, Türklerin ilk özel gazetesi Tercüman-ı Ahval 1860\'ta, muhalif Hürriyet ise 1868\'de yayımlanmıştır.'),
  ('Ramazan Kararnamesi (1875), Muharrem Kararnamesi (1881) ve Kaime\'nin çıkarılması (1840) olaylarını eskiden yeniye dizdiğimizde doğru sıra nedir?', 'Kaime, Ramazan Kararnamesi, Muharrem Kararnamesi', ['Muharrem Kararnamesi, Kaime, Ramazan Kararnamesi sırasıyla', 'Ramazan Kararnamesi, Kaime, Muharrem Kararnamesi', 'Kaime, Muharrem Kararnamesi, Ramazan Kararnamesi'], 'Kaime 1840\'ta çıkarılmış, borç ödemelerinin durdurulması 1875\'te, Muharrem Kararnamesi ise 1881\'de uygulanmıştır.'),
  ('Bir öğrenci "Osmanlı modernleşmesinde yeni okullar yalnızca medreseleri ortadan kaldırmak için açıldı" diyor. Bu görüşün eksikliği nedir?', 'Yeni okullar memur ve subay ihtiyacı için kurulmuş ve medreseler uzun süre varlığını sürdürmüştür', ['Yeni okullar yalnızca azınlık öğrencilerine açılmış ve medreselerden önce tamamen kapatılmış olduğundan', 'Medreseler yeni okullardan önce kapatılmıştır', 'Okullar yalnızca azınlıklara açılmıştır'], 'Osmanlı\'da yeni mektepler, memur ve subay ihtiyacı için açılmış, medreseler uzun süre devam etmiş; iki sistem paralel ilerlemiştir.'),
  ('Bir belgede şu ifadeler bulunmaktadır: "Kurucusu, geliri bir medrese ve çeşmenin giderlerine ayırmış, mütevelli olarak oğlunu atamış ve şartlarını sıralamıştır." Bu belge hangi türdendir?', 'Vakfiye', ['Berat', 'İlâm', 'Telhis'], 'Vakfiye, vakfeden kişinin vakfın amacını, gelir kaynaklarını ve yönetimini belirttiği hukuki belgedir.'),
  ('Bir seyyah Konya\'da yüksek keçe başlıklı, beyaz etekli dervişlerin ney eşliğinde dönerek ibadet ettiğini görüyor. Hangi tarikatın âyinine tanık olmuştur?', 'Mevlevilik', ['Bektaşilik', 'Rifailik', 'Halvetilik'], 'Semazenlerin uzun keçe başlık (sikke) ve beyaz tennure giyerek ney eşliğinde döndüğü ayin Mevlevi sema törenidir.'),
  ('Osmanlı\'da 1 mecidiye 20 kuruş ve 1 Osmanlı lirası 100 kuruş olduğuna göre 3 liralık ödemeyi kaç mecidiye ile yapabilirsiniz?', '15 mecidiye', ['12 mecidiye', '30 mecidiye', '60 mecidiye'], '3 lira 300 kuruştur; 300 / 20 = 15 mecidiye eder.'),
  ('Osmanlı\'da soyadı kullanılmadığı için insanlar birbirinden nasıl ayırt edilirdi?', 'Baba adı, meslek, memleket veya lakap kullanılarak', ['Numaralı kimlik kartlarıyla ve devletin dağıttığı soyadlarıyla her vatandaşı kaydederek', 'Mahalle muhtarının verdiği soyadıyla', 'Doğum tarihi sırasına göre'], 'Osmanlı\'da soyadı yoktu; kişiler baba adı, lakap, meslek veya memleketleriyle anılırdı. Soyadı Kanunu 1934\'te çıkarılmıştır.'),
  ('Osmanlı\'da "efendi" unvanı genel olarak kimlere verilirdi?', 'Okur yazar, ilmiye ve kalemiye mensuplarına', ['Köy ağalarına ve yalnızca askerî sınıfa mensup olan görevlilere', 'Yeniçeri ağasına', 'Konar-göçer aşiret reislerine'], 'Efendi unvanı ilmiye ve kalemiye mensuplarına ve okur yazar kişilere verilirdi; ağa ise saray hademeleri ve kırsal yerel kişiler için kullanılırdı.'),
  ('Aşağıdakilerden hangisi Osmanlı mutfağına Amerika kıtasından geçen bir üründür?', 'Mısır', ['Nohut', 'Patlıcan', 'Pirinç'], 'Mısır, domates ve patates gibi ürünler Coğrafi Keşifler sonrası Amerika\'dan dünyaya yayılmış; nohut, patlıcan ve pirinç Eski Dünya\'ya aittir.'),
  ('Piri Reis\'in 1513 tarihli dünya haritasını hangi padişaha sunduğu kabul edilir?', 'Yavuz Sultan Selim', ['Kanuni Sultan Süleyman', 'II. Bayezid', 'Fatih Sultan Mehmed'], 'Piri Reis, haritasını Mısır seferi sırasında 1517\'de Yavuz Sultan Selim\'e sunmuştur; haritada Atlas Okyanusu kıyıları ve Amerika gösterilmiştir.'),
  ('Osmanlı şenliklerinde esnafın alay hâlinde geçit yapmasının toplumsal anlamı nedir?', 'Loncaların toplumsal ve ekonomik gücünü görünür kılması', ['Esnafın vergi muafiyetinin sona erdiğini ve devlete teslim olduğunu göstermesi', 'Esnafın orduya katılmasını sağlaması', 'Esnafın şehirden çıkarılmasını simgelemesi'], 'Şenliklerde esnaf alayı, meslek gruplarının şehirdeki önemini gösteren ve ürünlerini sergileyen geçit törenleriydi.'),
  ('Yıldırım Bayezid\'in 1394\'te Abbasi halifesinden "Sultan-ı Rum" unvanını alması hangi amaçla yorumlanır?', 'Osmanlı hükümdarlığının İslam dünyasında meşruiyetini güçlendirme', ['Anadolu\'daki bütün beylikleri ortadan kaldırıp merkezi yönetimi tüm Anadolu\'ya yaymak', 'Bizans\'a vergi ödeme', 'Memluk Devleti\'ne bağlanma'], 'Bayezid, Kahire\'deki Abbasi halifesinden aldığı unvanla otoritesini dinî açıdan pekiştirmek istemiştir.'),
  ('Şeyhülislamların padişah tarafından kolayca görevden alınabilmesi, ilmiye sınıfı açısından neyi gösterir?', 'Üst düzey din bilginlerinin devlete bağımlılığının arttığını', ['İlmiye sınıfının siyasetten tamamen bağımsız olduğunu ve fetvaların bağlayıcı olmadığını', 'Fetvaların hiçbir etkisi olmadığını', 'Medreselerin kapatılacağını'], 'Şeyhülislamlar padişah tarafından atanıp görevden alındığından, fetva makamı zamanla siyasi etkiye açık hâle gelmiştir.'),
  ('Fransız asıllı olup Müslüman olarak Osmanlı hizmetine girdiği ve humbaracı birliğini Batı tarzında düzenlemeye çalıştığı bilinen paşa kimdir?', 'Humbaracı Ahmed Paşa (Bonneval)', ['Baron de Tott (Fransız topçu uzmanı)', 'Gevrekzâde Hasan Paşa', 'Cezayirli Hasan Paşa'], 'Bonneval, Humbaracı Ahmed Paşa adıyla Osmanlı hizmetine girmiş ve 18. yüzyılda humbaracı ocağını Batı usulüne göre örgütlemiştir.'),
  ('Yeniçeri ağası yokken ocağı Divan\'da temsil eden yardımcısı kimdir?', 'Kul kethüdası', ['Çorbacı', 'Sekbanbaşı', 'Kapıcıbaşı'], 'Kul kethüdası, yeniçeri ağasının yardımcısıydı ve ağa seferde ya da başkentte yokken ocağı temsil ederdi.'),
  ('Enderun\'un başı sayılan ve Bâbüssaâde\'yi koruyan en yüksek mevkideki ağa kimdir?', 'Bâbüssaâde Ağası (Kapı Ağası)', ['Darüssaâde Ağası (Kızlarağası)', 'Hazinedarbaşı', 'Silahdar Ağa'], 'Bâbüssaâde Ağası, Enderun\'un başıydı ve padişaha en yakın birim olan Enderun\'un işleyişini yönetirdi; Darüssaâde Ağası ise haremden sorumluydu.'),
  ('Padişahın yemeğinin kalitesini ve güvenliğini kontrol eden saray görevlisi hangisidir?', 'Çaşnigirbaşı', ['Silahdar', 'Rikâbdar', 'Kilerci'], 'Çaşnigir, padişahın yemeğini tadan ve kontrol eden görevlidir; bu önlem saray güvenliği ve sağlık kaygısını gösterir.'),
  ('Topçuların top arabalarını ve cephane taşıtlarını kullanan kapıkulu birliği hangisidir?', 'Top Arabacıları Ocağı', ['Cebeci Ocağı', 'Humbaracı Ocağı', 'Lağımcı Ocağı'], 'Top Arabacıları Ocağı, topçuların silah ve cephane arabalarını yöneten kapıkulu birliğidir; Cebeciler ise silah ve cephane yapımı ve taşımasıyla ilgilidir.'),
  ('19. yüzyıl Osmanlı vakıf yönetiminde "mazbut" ve "mülhak" vakıflar arasındaki temel fark nedir?', 'Mazbutlar doğrudan devletçe yönetilir, mülhaklar mütevelli idaresinde ama devlet denetiminde kalır', ['Mazbut vakıflar yalnızca ailelere ait olup halka açık değildir, mülhaklar ise halka açık hayır eserleridir', 'Mazbut vakıflar yalnızca cami, mülhak yalnızca çeşmedir', 'Her ikisi de doğrudan padişaha aittir'], 'Mazbut vakıflar Evkaf Nezareti tarafından doğrudan yönetilirken mülhak vakıfların yönetimi mütevellilere bırakılır, ancak nezaretin denetimine tabidir.'),
  ('İstanbul\'daki Unkapanı, Yağkapanı gibi adlardaki "kapan" sözcüğü neyi anlatır?', 'Toptan malların tartılıp satıldığı ve ticaret hâlinin bulunduğu yeri', ['Askerlerin toplandığı ve sefer hazırlığı yaptığı büyük ordugâh alanını', 'Askerî kışlayı', 'Kervan yolunu'], 'Kapan, un, yağ gibi toptan malların tartıldığı ve satıldığı toptan satış yeriydi; semtlerin adı bu işlevden gelir.'),
  ('1914\'te kadınlara yüksek öğrenim vermek amacıyla açılan Osmanlı yükseköğretim kurumu hangisidir?', 'İnas Darülfünunu (kadın üniversitesi)', ['Darülmuallimat (kız öğretmen yetiştiren okul)', 'Sanayi-i Nefise', 'Mekteb-i Tıbbiye'], 'İnas Darülfünunu, kızlara ayrı olarak 1914\'te kurulan, Osmanlı\'da kadınların üniversite düzeyinde eğitim aldığı ilk kurumdur.'),
  ('II. Abdülhamid yönetiminde "jurnal ve hafiye" sistemi neyi amaçlamıştır?', 'Muhalefeti ve devlet aleyhtarı faaliyetleri gizli ihbarlarla izlemeyi', ['Esnafı denetleyip fiyat ve ölçü kontrolü yapmayı ve narh uygulamalarını izlemeyi', 'Nüfus sayımı yapmayı', 'Vergi toplamayı'], 'Jurnal, gizli ihbar raporlarıdır; hafiyeler aracılığıyla muhalefet izlenir ve baskı sağlanırdı, bu dönem otoriter yönetim biçimiyle anılır.'),
  ('17. yüzyılda "Kadızadeliler" olarak anılan dinî hareketin temel eleştirisi nedir?', 'Tasavvuf uygulamalarını, kahve, tütün ve müzik gibi alışkanlıkları dinde bidat sayması', ['Medreselerin kapatılıp eğitimin tamamen Batı tarzı okullara devredilmesini ve yeniçerilerin kaldırılmasını istemesi', 'Yeniçerilerin kaldırılmasını savunması', 'Padişahın tahttan inmesini istemesi'], 'Kadızadeliler, Birgivi Mehmed Efendi\'nin görüşlerinden etkilenerek tekke ve tasavvuf uygulamalarını, kahve, tütün ve çalgı gibi şeyleri bidat sayan muhafazakâr bir harekettir.'),
  ('Osmanlı Devleti 1299\'dan 1922\'ye kadar kaç padişah tarafından yönetilmiştir?', '36 padişah', ['28 padişah', '41 padişah', '45 padişah'], 'Osmanlı Devleti, Osman Bey\'den VI. Mehmed\'e kadar 36 padişah tarafından yönetilmiştir.'),
  ('Aşağıdakilerden hangisi Topkapı Sarayı\'nın avlularında yer alan bir yapı değildir?', 'Süleymaniye Camii', ['Arz Odası', 'Revan Köşkü', 'Kubbealtı'], 'Arz Odası üçüncü, Revan Köşkü dördüncü, Kubbealtı ikinci avluda yer alır; Süleymaniye Camii ise saray dışında, bağımsız bir külliyedir.'),
  ('Aşağıdakilerden hangisi kapıkulu ocakları arasında sayılmaz?', 'Akıncılar', ['Yeniçeriler ve cebeciler', 'Topçu ve humbaracılar', 'Lağımcılar ve top arabacıları'], 'Akıncılar Rumeli sınırında düzenli maaşsız hafif süvari idi, kapıkulu ocağı değildi. Yeniçeri, cebeci, topçu, humbaracı, lağımcı ve top arabacıları kapıkulu ocaklarındandır.'),
  ('Aşağıdakilerden hangisi ilmiye sınıfına mensup bir görevli değildir?', 'Defterdar', ['Müderris ve danişmend', 'Kadı ve nâib', 'Müftü ve şeyhülislam'], 'Defterdar maliyeyi yürüten kalemiye mensubudur; müderris, kadı ve müftü ise ilmiyedendir.'),
  ('Tarikatlar ve özellikleri ile ilgili aşağıdaki bilgilerden hangisi doğru değildir?', 'Mevlevilik - yeniçeri ocağının pîri', ['Bektaşilik - dört kapı kırk makam öğretisi', 'Mevlevilik - sema ve ney', 'Nakşibendilik - Halidiyye kolu'], 'Yeniçeri ocağının pîri Hacı Bektaş-ı Veli\'dir; Mevlevilik sema ve ney ile anılan, ayrı bir tarikattır.'),
  ('Osmanlı vergilerinin anlamlarıyla ilgili hangi ifade doğru değildir?', 'Nüzul - gümrük vergisi', ['Cizye - gayrimüslim baş vergisi', 'Öşür - ürünün onda biri', 'Avarız - olağanüstü savaş vergisi'], 'Nüzul sefer sırasında orduya zahire sağlamak için alınan olağanüstü teklifti; gümrük vergisi ise ayrı bir gelir kalemidir.'),
  ('Osmanlı hamamlarında sıcaklık bölümünün ortasında bulunan, yassı mermerden yapılmış ve üzerinde terleme ile masaj yapılan taşa ne denir?', 'Göbek taşı', ['Mihrap taşı', 'Sadaka taşı', 'Menzil taşı'], 'Göbek taşı, hamamın ısıtılmış sıcaklık bölümünde ortada bulunan, sıcak mermer yüzeyi terlemek ve masaj için kullanılan taştır.'),
  ('Peçevi\'ye göre İstanbul\'da ilk kahvehaneleri 16. yüzyılın ortasında Tahtakale\'de açan iki kişi hangi şehirlerdendir?', 'Halep ve Şam', ['Bağdat ve Basra', 'Kahire ve İskenderiye', 'Kudüs ve Mekke'], 'Peçevi, Halepli Hakem ve Şamlı Şems adlı iki kişinin Tahtakale\'de ilk kahvehaneleri açtığını anlatır.'),
  ('Mimar Sinan\'ın II. Selim döneminde Ayasofya\'ya yaptığı eklemeler hangileridir?', 'İki minare ve payandalar', ['Kubbe ve sütun sıralarının ilavesi', 'Çeşme ve şadırvan', 'Bahçe ve türbe'], 'Sinan, Ayasofya\'yı korumak için payandalar ve iki yeni minare ekleyerek yapının dayanıklılığını artırmıştır.'),
  ('Osmanlı kitabelerinde yapının tamamlanma yılını gösteren, şiir dizelerindeki harflerin sayı değerlerinin toplamıyla bulunan uygulamaya ne ad verilir?', 'Tarih düşürme (ebced)', ['Tuğra çekme (padişah imzası)', 'Berat yazma', 'Siyakat'], 'Tarih düşürme, bir şiirin dizesindeki harflerin ebced değerlerinin toplanmasıyla yapının tarihini bulmaktır; çeşme ve cami kitabelerinde yaygındır.'),
  ('Karagöz oyununda oyuncuya (perdeyi oynatan kişiye) ne ad verilir?', 'Hayalî', ['Meddah', 'Pişekâr', 'Kavuklu'], 'Hayalî, Karagöz perdesinde tasvirleri hareket ettiren, seslendirilen karakterleri canlandıran sanatçıdır.'),
  ('Karagöz oyununda oyunun giriş bölümüne ne ad verilir?', 'Mukaddime', ['Muhavere', 'Fasıl', 'Bitiş'], 'Karagöz oyunu mukaddime, muhavere, fasıl ve bitiş bölümlerinden oluşur; mukaddime giriş bölümüdür.'),
  ('Meddahların hikâye anlatırken yanlarında bulundurdukları iki eşya hangisidir?', 'Mendil ve sopa', ['Davul ve zil', 'Perde ve fener', 'Nargile ve cezve'], 'Meddah, mendil ve sopayı farklı karakterleri canlandırmak için kullanır; sahnesi yoktur, yalnızca anlatı ve taklitle çalışır.'),
  ('Osmanlı halk takvimine göre yılı yaz ve kış olmak üzere ikiye ayıran iki gün hangileridir?', 'Hıdırellez ve Kasım', ['Nevruz ve Mevlid', 'Arife ve Muharrem', 'Hıdırellez ve Nevruz'], 'Halk takvimine göre Hıdırellez (6 Mayıs) yaz mevsiminin, Kasım günü (8 Kasım) kış mevsiminin başlangıcı sayılırdı.'),
  ('1829 Kıyafet Nizamnamesi ile memurlar için fes zorunlu hâle gelirken hangi grup sarık kullanmaya devam etmiştir?', 'Ulema (din bilginleri)', ['Askerler (yeni ordu mensupları)', 'Esnaf', 'Çiftçiler'], '1829 kıyafet düzenlemesi devlet görevlileri için fesi zorunlu kılmış, ilmiye mensupları ise geleneksel sarıklarını korumuştur.'),
  ('1844\'te basılan ve ilk Türkçe basılı yemek kitabı kabul edilen eser hangisidir?', 'Melceü\'t-Tabbâhîn', ['Mecelle', 'Seyahatname', 'Takvim-i Vekayi'], 'Mehmed Kâmil\'in Melceü\'t-Tabbâhîn\'i, Osmanlı mutfağını ve yemek tariflerini kaydeden, basılı ilk yemek kitabı olarak kabul edilir.'),
  ('Osmanlı Devleti\'nin ilk daimi elçiliğini 1793\'te hangi başkentte açtığı kabul edilir?', 'Londra', ['Paris', 'Viyana', 'Petersburg'], 'III. Selim döneminde 1793\'te Londra\'da daimi elçilik açılmış, Osmanlı diplomasisi geçici elçiliklerden sürekli temsilciliğe geçmiştir.'),
  ('18. yüzyılda yabancı elçiliklerden berat alarak ayrıcalık kazanan Osmanlı tebaası gayrimüslim tüccarların bu uygulamadan temel kazancı neydi?', 'Vergi ve hukuk bakımından yabancı tebaa gibi ayrıcalıklı korunmaları', ['Devlet memuru olabilmeleri ve padişahın doğrudan maaş bağlaması hakkı', 'Padişah maaşı almaları', 'Askerlikten tamamen çıkarılmaları'], 'Beratlı tüccarlar yabancı devletlerin korumasıyla Osmanlı vergi ve yargısı karşısında ayrıcalık kazanmış, bu durum iç ticarette eşitsizlik yaratmıştır.'),
  ('İstanbul Arkeoloji Müzesi binasını 1891\'de tasarlayan, Osmanlı Bankası\'nı da yapan Levanten mimar kimdir?', 'Alexandre Vallaury', ['Raimondo D\'Aronco', 'Vedat Tek', 'Mimar Kemaleddin'], 'Vallaury, Arkeoloji Müzesi, Osmanlı Bankası ve Sanayi-i Nefise gibi yapıları tasarlayan, Fransa\'da eğitim görmüş Levanten bir mimardır.'),
  ('İstanbul\'daki Haydarpaşa Garı\'nı 1908\'de tamamlayan mimarlar hangi ülkenin vatandaşıdır?', 'Almanya', ['Fransa', 'İtalya', 'Avusturya'], 'Haydarpaşa Garı, Alman mimarlar Otto Ritter ve Helmuth Cuno tarafından yapılmış; Osmanlı-Alman yakınlaşmasını ve Bağdat Demiryolu\'nu simgeler.'),
  ('İstanbul Şehir Tiyatroları\'nın öncüsü sayılan ve 1914\'te açılan sanat okulu hangisidir?', 'Darülbedayi', ['Darülelhan', 'Sanayi-i Nefise', 'Mekteb-i Sultani'], 'Darülbedayi, 1914\'te açılan ve tiyatro eğitimi veren kurumdur; İstanbul Şehir Tiyatroları\'nın kökenidir.'),
  ('Bir cilt ustası kapağın ortasına madalyon biçimli bir süs yapıyor. Bu süsün adı nedir?', 'Şemse', ['Zerefşan', 'Murakka', 'Hatayi'], 'Şemse, ciltlerin kapağında ortada bulunan madalyon biçimli süslemedir; Osmanlı cilt sanatının tipik unsurudur.'),
  ('Osmanlı medreselerinde Hâriç ve Dâhil sınıflarına ayrılma neyi gösterir?', 'Medreselerin öğretim düzeyine göre alt ve üst basamaklara ayrıldığını', ['Medreselerin yalnızca dinî ve fen derslerini ayrı ayrı verdiğini ve öğrenciyi sınav yapmadan mezun ettiğini', 'Medreselerin kız ve erkek diye ikiye ayrıldığını', 'Medreselerin Anadolu ve Rumeli diye ikiye ayrıldığını'], 'Hâriç medreseler alt, Dâhil medreseler daha üst düzeydi; ders ve ücret basamaklarıyla müderris yükselmesi bu kademelere göre yürürdü.'),
  ('Osmanlı\'da müderrislerin günlük ücretinin kademeyi belirlemesi (20\'li, 40\'lı, 50\'li medreseler) neyi gösterir?', 'Medrese basamaklarının hem ders düzeyi hem ücret düzeyiyle belirlendiğini', ['Müderrislerin ücret almayıp tamamen gönüllü hizmet verdiğini ve tüm medreselerin eşit düzeyde olduğunu', 'Medreselerin tamamının eşit olduğunu', 'Müderrislerin yalnızca vakıf geliriyle geçindiğini'], 'Müderris ücreti günlük akçeyle ifade edilir ve medreselerin saygınlığı bu ücretle ölçülürdü; bu da yükselme düzeninin bir parçasıydı.'),
  ('Bir vakıf kütüphanesinde kitapların düzeninden sorumlu görevli kimdir?', 'Hâfız-ı kütüb', ['Müstensih', 'Müderris', 'Muhtesib'], 'Hâfız-ı kütüb, kütüphane memuruydu; kitapların korunması, kataloglanması ve okuyuculara sunulmasıyla ilgilenirdi.'),
  ('Osmanlı ordusunda ve devlet töreninde tuğ (at kuyruğu bayrağı) sayısının farklı olması neyi gösterirdi?', 'Makam ve yetki derecesini', ['Askerin yaşını ve görev süresini', 'Ordunun toplanma yerini', 'Savaşın süresini'], 'Tuğ sayısı hükümdar, sadrazam, vezir ve beylerbeyi gibi makamların derecesini gösteren bir protokol simgesiydi.'),
  ('Osmanlı tekkelerinde şeyhin makamında oturan ve tarikatı yöneten kişiye ne ad verilir?', 'Postnişin', ['Müezzin', 'Kayyum', 'Hatip'], 'Postnişin, post üzerinde oturan kişi anlamındadır; tekkenin yöneticisi ve tarikatın temsilcisi olan şeyhtir.'),
  ('Osmanlı\'da 1862\'de kurulan ve devlet harcamalarını denetleyen, Sayıştay\'ın öncüsü sayılan kurum hangisidir?', 'Divan-ı Muhasebat', ['Şûrâ-yı Devlet', 'Meclis-i Vâlâ', 'Defterdarlık'], 'Divan-ı Muhasebat, bütçe ve hesapların denetlenmesi amacıyla kurulmuş, Sayıştay\'ın temelini oluşturmuştur.'),
  ('1877 İdare-i Belediye Kanunu\'nun Osmanlı şehirlerinde yarattığı temel gelişme nedir?', 'Belediye teşkilatının İstanbul dışına yayılarak yerel yönetimlerin düzenlenmesi', ['Belediyelerin kaldırılıp tüm şehir yönetiminin kadılara geri verilmesi ve mahalle meclislerinin kapatılması', 'Vergilerin padişaha devredilmesi', 'Mahallelerin kapatılması'], '1877 Belediye Kanunu, şehir yönetiminde seçilmiş meclislerin rolünü artırmış, belediyecilik uygulamalarını taşraya yaymıştır.'),
  ('1878\'de Tercüman-ı Hakikat gazetesini çıkaran ve halkı bilgilendirmeyi amaçlayan Osmanlı aydını kimdir?', 'Ahmet Mithat Efendi', ['Şinasi', 'Namık Kemal', 'Ziya Paşa'], 'Ahmet Mithat Efendi, Tercüman-ı Hakikat gazetesiyle ve çok sayıdaki eseriyle halkı eğitmeyi amaçlayan öncü bir yazardır.'),
  ('Ahmet İhsan Tokgöz\'ün 1891\'de İstanbul\'da yayımladığı ve Edebiyat-ı Cedide topluluğunun çevresinde toplandığı dergi hangisidir?', 'Servet-i Fünun', ['Tasvir-i Efkâr', 'Ceride-i Havadis', 'Tanin'], 'Servet-i Fünun, fen ve edebiyat haberlerini içeren bir dergi olarak başladı, sonradan Edebiyat-ı Cedide topluluğunun yayın organı oldu.'),
  ('İstanbul\'da Avrupa yakasındaki "Tatlısular" olarak anılan ve Lale Devri\'nde saray ve halk için mesire yeri olan yer neresidir?', 'Kâğıthane', ['Yıldız Sarayı bahçesi', 'Çamlıca', 'Eyüp'], 'Kâğıthane, Avrupa Tatlısuları olarak anılan, III. Ahmed döneminde Sadabad ile gelişen mesire alanıdır; Anadolu yakasındaki Tatlısular ise Göksu\'dur.'),
  ('Osmanlı\'da evlilik ve boşanma kurallarını düzenleyen, kadınlara bazı yeni haklar tanıyan 1917 tarihli düzenleme hangisidir?', 'Hukuk-ı Aile Kararnamesi', ['Mecelle', 'Tapu Kanunu', 'Cemiyetler Kanunu'], 'Hukuk-ı Aile Kararnamesi, Osmanlı\'da aile hukukunu yazılı bir düzene sokarak evlilik ve boşanmada kadınlara bazı güvenceler getirmiştir.'),
  ('1917 Hukuk-ı Aile Kararnamesi\'nde kadının nikâh sözleşmesine ikinci eş almama şartı koyabilmesi neyi gösterir?', 'Kadınların evlilik sözleşmesinde haklarını yazılı güvenceye alabildiğini', ['Çok eşliliğin yasal olarak zorunlu hâle geldiğini ve kadınların bu konuda hiçbir hakkı olmadığını', 'Kadınların askerlik yapabildiğini', 'Evlenme yaşının düşürüldüğünü'], 'Kararname, kadının evlilik sözleşmesine şart koymasına izin vererek hukuki konumunu güçlendirmiş, aile hukukunda yeni bir yön göstermiştir.'),
  ('IV. Mehmed\'in hasekisi olup II. Mustafa ve III. Ahmed\'in annesi olan, Üsküdar\'daki Yeni Valide Camii\'ni yaptıran valide sultan kimdir?', 'Gülnuş Sultan (Emetullah)', ['Kösem Sultan (Mahpeyker, IV. Murad\'ın annesi)', 'Turhan Sultan', 'Safiye Sultan'], 'Gülnuş Sultan, IV. Mehmed\'in haseki olan eşi, II. Mustafa ve III. Ahmed\'in annesi olup Üsküdar\'daki Yeni Valide Camii\'ni yaptırmıştır.'),
  ('1770 Çeşme baskınından sonra donanmayı ve tersaneyi yeniden düzenleyen, Cezayirli unvanıyla bilinen kaptan-ı derya kimdir?', 'Cezayirli Gazi Hasan Paşa', ['Piyale Paşa', 'Kılıç Ali Paşa', 'Barbaros Hayreddin'], 'Cezayirli Gazi Hasan Paşa, Çeşme yenilgisinin ardından donanmayı ve tersaneyi modernleştirmeye çalışmış, Mühendishane-i Bahri\'nin kurulmasına da öncülük etmiştir.'),
  ('Padişah, valilerin zulmünü önlemek için bir emir çıkarıyor. Bu belge nedir?', 'Adaletname', ['Hatt-ı hümâyûn', 'Nasihatname', 'Ahidname'], 'Adaletname, padişahın zulüm ve haksızlıkları gidermek, vergi suistimallerini önlemek amacıyla çıkardığı emirdir.'),
  ('Osmanlı ceza hukukunda "kısas" kavramı neyi ifade eder?', 'Mağdura uğradığı zarar ölçüsünde karşılık verme hakkı tanınmasını', ['Hâkimin takdirine bağlı olarak cezanın miktarını belirleyip artırabilmesini', 'Suçlunun para cezasından muaf olmasını', 'Padişahın cezaları affetmesini'], 'Kısas, mağdurun uğradığı zarara denk bir karşılık hakkı tanıyan, özellikle öldürme ve yaralama suçlarında kullanılan sabit bir cezadır.'),
  ('Pera\'da 1892\'de Orient Express yolcuları için yapılan lüks otel hangisidir?', 'Pera Palas', ['Çırağan Palas', 'Tokatlıyan', 'Park Otel'], 'Pera Palas, Alexandre Vallaury tarafından Orient Express yolcuları için yapılan, İstanbul\'un Avrupa tarzı yaşamının simgesi lüks bir oteldir.'),
  ('Divan-ı Hümayun\'un haftada dört gün toplanması neyi gösterir?', 'Devlet işlerinin düzenli ve belirli günlerde görüşülüp karara bağlandığını', ['Divanın yalnızca bayram günlerinde toplanıp kararları padişahın tek başına aldığını', 'Divanın yılda dört kez toplandığını', 'Padişahın divanı hiç görmediğini'], 'Divan Cumartesi\'den Salı\'ya kadar toplanır, devlet işleri düzenli bir takvimle yürütülürdü.'),
  ('19. yüzyılın büyük Türk müziği bestecilerinden Hammâmîzâde İsmail Dede Efendi hangi tarikatla ilişkilendirilir?', 'Mevlevilik', ['Bektaşilik', 'Nakşibendilik', 'Halvetilik'], 'Dede Efendi, Mevlevi tarikatına mensup ve Mevlevi âyin müziğinin büyük bestecilerinden olarak anılır.'),
  ('Osmanlı Devleti\'nde Yörüklerin yaylak ve kışlak arasında mevsimlik göç etmelerinin temel nedeni nedir?', 'Hayvanlarına mevsime göre otlak ve su bulmak', ['Düşman saldırısından ve vergi toplayıcılarından kaçmak', 'Vergi toplayıcılarından saklanmak', 'Dinî törenlere katılmak'], 'Yörükler büyük ölçüde hayvancılıkla geçindiğinden mevsimlere göre yayla ve kışlak arasında göç ederek otlak ve su arardı.'),
  ('Celî sülüs yazısında ustalaşan ve Osmanlı hat sanatında önemli yeri olan, 1757-1826 yılları arasında yaşamış hattat kimdir?', 'Mustafa Râkım', ['Şeyh Hamdullah', 'Hâfız Osman', 'Mehmed Esad Yesârî'], 'Mustafa Râkım, celî sülüs yazısında ve süslü levhalarda olağanüstü başarı göstermiş, Osmanlı hat sanatının ünlü ustalarındandır.'),
  ('Sirkeci Garı\'nı 1890\'da yapan, Doğu mimarisinden esinlenen Alman mimar kimdir?', 'August Jasmund', ['Otto Ritter', 'Helmuth Cuno', 'Alexandre Vallaury'], 'August Jasmund, Orient Express yolcularının geldiği Sirkeci Garı\'nı Doğu motifli bir üslupla tasarlamıştır.'),
  ('Tanzimat\'ı başlatan 1839 metni, padişah adına yayımlanan hangi türde bir belgedir?', 'Hatt-ı Şerif (padişah yazısı)', ['Fetva (müftünün verdiği hukuki görüş)', 'Berat', 'Telhis'], 'Gülhane Hatt-ı Şerifi, padişahın adıyla yayımlanan ve Tanzimat\'ı başlatan padişah yazısıdır; hatt-ı şerif bu tür resmî yazılar için kullanılırdı.'),
  ('Donizetti Paşa\'nın bestelediği ve ilk Osmanlı marşı sayılan eser hangisidir?', 'Mahmudiye Marşı', ['Reşadiye Marşı', 'Hamidiye Marşı', 'Mecidiye Marşı'], 'Mahmudiye Marşı, II. Mahmud adına Donizetti tarafından bestelenmiştir ve Osmanlı\'nın Batı tarzı ilk resmî marşıdır.'),
  ('Osmanlı halkının günlük hayatta tatlandırıcı olarak şekerden çok hangi ürünleri kullandığı söylenebilir?', 'Pekmez ve bal', ['Pirinç ve mısır', 'Süt ve yoğurt', 'Zeytinyağı ve yumurta'], 'Şeker pahalı olduğundan geniş halk kitleleri genellikle pekmez ve bal kullanır, şeker saray ve zenginler arasında yaygındı.'),
  ('Şam\'dan çıkan hac kafilesinin başında devlet adına yönetimi sağlayan görevli kimdir?', 'Emîrü\'l-hac', ['Surre emini', 'Şeyhülislam', 'Müftü'], 'Emîrü\'l-hac, hac kafilesinin güvenliği, düzeni ve yönetiminden sorumlu görevliydi ve genellikle önemli bir vali veya beyin işiydi.'),
  ('Osmanlı\'da evlilikte aileler arasındaki görüşmelerle gelin ve damat adayı belirlenmesi yöntemine ne ad verilirdi?', 'Görücü usulü', ['Kız kaçırma geleneği', 'Berdel', 'Bedel'], 'Görücü usulünde aileler ve görücüler aracılığıyla evlilik teklifleri yapılır, adaylar çoğu zaman birbirlerini evlilikten önce tanımazdı.'),
  ('Osmanlı mezarlıklarında mezar taşlarına ne ad verilir?', 'Şahide', ['Kitabe', 'Sebil', 'Mihrap'], 'Şahide, yazılı ve başlıklı mezar taşıdır; başlık biçimi ve süslemeleriyle ölen kişinin kimliğini ve statüsünü gösterir.'),
  ('Bir yapının girişindeki, yapım yılını ve yapanı belirten yazılı levhaya ne denir?', 'Kitabe', ['Şahide', 'Cumba', 'Revak'], 'Kitabe, bir yapının yapılış nedenini, yapanını ve tarihini belirten yazılı levhadır; genellikle şiir biçiminde de olurdu.'),
  ('Osmanlı kadı mahkemesinde bir kişi eşi ile bir oğlunu bırakarak ölüyor. Çocuk olduğu için eşin payı 1/8 ise, 800 akçelik terekeden eşe kaç akçe düşer?', '100 akçe (1/8)', ['200 akçe', '400 akçe', '700 akçe (oğlunun payı)'], 'Çocuk varsa eşin payı sekizde birdir; 800 x 1/8 = 100 akçe eşe, kalan 700 akçe oğula kalır.'),
  ('Osmanlı kadı mahkemesinde bir kişi yalnızca bir oğul ve bir kız bırakarak ölüyor. Erkek, kızın iki katı pay alıyorsa 900 akçelik terekeden kıza kaç akçe düşer?', '300 akçe (1/3)', ['150 akçe', '450 akçe', '600 akçe (oğlunun payı)'], 'Pay oranı 2:1 olduğundan toplam üç pay vardır. 900 / 3 = 300 akçe kıza, 600 akçe oğula düşer.'),
  ('Bir öğrenci "Osmanlı mahkemeleri yalnızca erkeklere hizmet ederdi" diyor. Bu görüşü en çok hangi bilgi çürütür?', 'Şer\'iyye sicillerinde kadınların miras, mülk ve vakıf davalarının kayıtlı olması', ['Kadılara düzenli maaş bağlanması ve mahkemelerin cami avlularında toplanması gerekliliği', 'Mahkemelerin camilerde toplanması', 'Sicillerin Arapça yazılması'], 'Kadınların mahkemeye başvurup mirasçı ve mülk sahibi olarak kaydedilmesi, mahkemelerin onlara da hizmet verdiğini gösterir.'),
  ('Bir öğrenci "Osmanlı ordusu 16. yüzyılda yalnızca atlı süvariye dayanıyordu" diyor. Hangi bilgi bu görüşü çürütür?', 'Yeniçerilerin tüfek ve topla savaşması ve tabur cengi taktiğinin uygulanması', ['Akıncıların hafif süvari olması ve sipahilerin tımarlı atlı asker olarak sefere gelmesi', 'Sipahilerin tımarla beslenmesi', 'Mehterin savaşa katılması'], 'Kapıkulu piyadesi ateşli silah kullanmış, tabur cengi gibi taktiklerde top ve tüfekten yararlanmıştır; bu ordunun yalnızca süvariye dayanmadığını gösterir.'),
  ('Bir öğrenci "19. yüzyıla kadar Osmanlı\'da eğitim yalnızca medresede veriliyordu" diyor. Hangi bilgi bu görüşü çürütür?', 'Enderun\'da saray için devlet adamı yetiştirilmesi ve 1773\'te Mühendishane\'nin açılması', ['Medreselerin vakıflarla desteklenmesi ve sıbyan mekteplerinin mahalle içinde bulunup müderrislerin ders vermesi', 'Sıbyan mekteplerinin mahallede olması', 'Müderrislerin ders vermesi'], 'Enderun saray eğitimi veriyor, 18. yüzyılda Batı tarzı mühendislik okulları açılıyordu; eğitim yalnızca medreseden ibaret değildi.'),
  ('Bir öğrenci "Osmanlı hukuku yalnızca şer\'î hukuka dayanıyordu" diyor. Hangi bilgi bu görüşü çürütür?', 'Padişah kanunnamelerinin ve örfî hukukun da uygulanması', ['Kadıların Hanefi mezhebine göre hüküm vermesi ve fetvaların bağlayıcı olması', 'Fetva sisteminin bulunması', 'Vakıfların şer\'î olması'], 'Osmanlı\'da şer\'î hukukun yanında padişahın kanunnameleri ve örfî hukuk da uygulanıyordu; iki hukuk alanı birlikte işlerdi.'),
  ('Bir öğrenci "Osmanlı toplumu yenilikleri hiç kabul etmedi" diyor. Hangi gelişme bu görüşü en çok çürütür?', 'Lale Devri\'nde matbaa, 19. yüzyılda telgraf, fotoğraf ve tramvayın kullanılması', ['Medreselerin varlığını sürdürmesi ve loncaların esnaf üzerindeki denetimi sürdürmesi', 'Loncaların sürmesi', 'Vakıfların yaygın olması'], 'Matbaa, telgraf, fotoğraf ve tramvay gibi yeniliklerin Osmanlı\'da kullanılması, toplumun değişime açık yönlerini gösterir.'),
  ('Bir öğrenci "Osmanlı kadını kamusal hayatta hiç yer almıyordu" diyor. Hangi bilgi bu görüşü zayıflatır?', 'Kadınların vakıf kurması, mülk sahibi olması ve 19. yüzyılda gazete ve okullarda yer alması', ['Kadınların evde oturması, haremin varlığı ve çarşafın yaygın olması nedeniyle hiçbir kamusal rol üstlenmemesi', 'Haremin varlığı', 'Çarşafın yaygın olması'], 'Kadınlar vakıf kurmuş, mülk sahibi olmuş ve sonraki dönemlerde kadın gazeteleri ile okullarda yer almıştır.'),
  ('Sultanahmet Camii\'nin altı minareli olması hangi tartışmaya yol açmıştır?', 'Mekke\'deki Mescid-i Haram\'ın minare sayısıyla eşitlik olarak görülmesi', ['Caminin çok pahalıya mal olması ve inşaat için devlet hazinesinin boşalması', 'Minarelerin kubbeden büyük olması', 'Caminin kıble yönünün hatalı olması'], 'Altı minare, o dönem Mescid-i Haram\'ın minare sayısıyla benzer bulunduğu için tartışılmış; Mekke\'ye yeni bir minare eklenerek denge sağlanmıştır.'),
  ('Hicaz Demiryolu (1900-1908), Telgraf (1855) ve Tünel (1875) kuruluşlarını en eskiden en yeniye dizdiğimizde sıra nasıldır?', 'Telgraf, Tünel, Hicaz Demiryolu', ['Tünel, Telgraf, Hicaz Demiryolu sıralamasıyla', 'Hicaz Demiryolu, Telgraf, Tünel', 'Telgraf, Hicaz Demiryolu, Tünel'], 'Osmanlı\'da telgraf 1855\'te, Tünel 1875\'te, Hicaz Demiryolu ise 1900-1908 arasında yapılmıştır.'),
  ('Gülhane Hatt-ı Şerifi (1839), Islahat Fermanı (1856) ve Kanun-ı Esasi (1876) belgelerini eskiden yeniye dizdiğimizde sıra nasıldır?', 'Gülhane Hatt-ı Şerifi, Islahat Fermanı, Kanun-ı Esasi', ['Islahat Fermanı, Gülhane Hatt-ı Şerifi, Kanun-ı Esasi sıralamasıyla', 'Kanun-ı Esasi, Islahat Fermanı, Gülhane Hatt-ı Şerifi', 'Gülhane Hatt-ı Şerifi, Kanun-ı Esasi, Islahat Fermanı'], 'Tanzimat 1839\'da, Islahat Fermanı 1856\'da, I. Meşrutiyet\'in anayasası olan Kanun-ı Esasi 1876\'da ilan edilmiştir.'),
  ('Fatih Camii (1470), II. Bayezid Camii (1506) ve Süleymaniye (1557) yapılarını eskiden yeniye dizdiğimizde sıra nasıldır?', 'Fatih Camii, II. Bayezid Camii, Süleymaniye', ['II. Bayezid Camii, Fatih Camii, Süleymaniye sıralamasıyla', 'Süleymaniye, Fatih Camii, II. Bayezid Camii', 'Fatih Camii, Süleymaniye, II. Bayezid Camii'], 'Fatih külliyesi 15. yüzyılın sonuna doğru, Bayezid Külliyesi 16. yüzyılın başında, Süleymaniye ise 16. yüzyılın ortasında yapılmıştır.'),
  ('Osmanlı\'nın son büyük hamamlarından olan ve 1741\'de I. Mahmud tarafından yaptırılan İstanbul hamamı hangisidir?', 'Cağaloğlu Hamamı', ['Çemberlitaş Hamamı', 'Gedikpaşa Hamamı', 'Beyazıt Hamamı'], 'Cağaloğlu Hamamı, I. Mahmud döneminde Ayasofya Külliyesi\'nin vakıf geliri için yapılmış, günümüze ulaşmış hamamlardandır.'),
  ('Sultanahmet Meydanı\'ndaki Alman Çeşmesi hangi olayın anısına yapılmıştır?', 'Alman İmparatoru II. Wilhelm\'in 1898\'deki İstanbul ziyaretinin', ['Alman İmparatoru\'nun taht değişikliğinin ve Osmanlı\'ya askerî heyet göndermesinin', 'Osmanlı-Alman ittifakının 1914\'te yapılmasının', 'Alman mimarların İstanbul\'a gelişinin'], 'Alman Çeşmesi, II. Wilhelm\'in 1898 ziyaretinin anısına hediye edilmiş, 1901\'de açılmıştır; iki devlet arasındaki yakınlaşmayı gösterir.'),
  ('İstanbul\'daki Eminönü semtinin adı hangi görevden gelmektedir?', 'Gümrük emini', ['Şehremini', 'Defter emini', 'Surre emini'], 'Eminönü, gümrük eminlerinin görev yaptığı iskele ve gümrük binası yakınında bulunduğundan "emin önü" olarak anılmış, semtin adı bu göreve dayanır.'),
  ('İstanbul\'daki Mahmutpaşa semtinin adı hangi devlet adamından gelir?', 'Fatih\'in sadrazamı Mahmud Paşa', ['Kanuni\'nin sadrazamı İbrahim Paşa', 'Köprülü Mehmed Paşa', 'Sokollu Mehmed Paşa'], 'Mahmutpaşa, Fatih\'in sadrazamı Mahmud Paşa\'nın yaptırdığı külliye nedeniyle bu adı almıştır.'),
  ('Sahaflar Çarşısı\'nın Beyazıt\'ta bulunması ve kitap ticaretinin orada yoğunlaşması neyi gösterir?', 'Kitapçılığın medrese ve külliye çevresinde, ilim merkezlerine yakın gelişmesini', ['Kitapların yalnızca saray çevresinde satılıp medrese çevresinde hiç kitapçılık yapılmadığını', 'Kitap ticaretinin yabancılara bırakılmasını', 'Beyazıt\'ın askerî bölge olmasını'], 'Sahaflar, yakınındaki medrese ve külliyelerin öğrenci ve bilginlerine hizmet ettiğinden ilim merkezlerinin yanında yoğunlaşmıştır.'),
  ('Osmanlı\'da gümrük emininin işleyişte önemli olmasının temel nedeni nedir?', 'Dış ticaretten alınan gümrük vergisinin devlet gelirlerinde önemli yer tutması', ['Padişahı korumak ve sarayda yapılan harcamaları denetleyerek hazineye gelir sağlamak', 'Ordunun yemek işlerini yürütmesi', 'Vakıfları yönetmesi'], 'Gümrük, dış ticaretten alınan vergiyi toplayan, hazine gelirleri için önemli bir kaynak olduğundan gümrük eminleri kritik görevlilerdi.'),
  ('Osmanlı\'da bir kadının mahkemede vekil aracılığıyla davasını sürdürebilmesi neyi gösterir?', 'Kadınların hukuki işlemlerde temsil edilme ve taraf olma imkânına sahip olduğunu', ['Kadınların yargıç olarak görev yapıp mahkemelerde hüküm verebildiğini ve kadı atanabildiğini', 'Kadınların mahkemeye hiç çıkamadığını', 'Davaların her zaman gizli yapıldığını'], 'Şer\'iyye sicillerinde kadınların vekil tayin ederek davalarını yürüttüğü görülür; bu hukuki ehliyetlerinin göstergesidir.'),
  ('Osmanlı camilerinin duvarlarında ve kubbe içlerinde kullanılan geometrik ve bitkisel süslemelerin figür içermemesinin temel nedeni nedir?', 'Dinî anlayış gereği canlı tasvirinden kaçınılması', ['Boyaların yetersiz olması ve ustaların renkli süsleme yapmasının yasak olması', 'Ustaların resim bilmemesi', 'Padişahların yasaklaması'], 'İslam sanatında dinî yapılarda canlı figür yerine hat, geometrik ve bitkisel süsleme kullanılması dinî hassasiyetle ilgilidir.'),
  ('Padişahın atlarının bakımından ve ahırlarından sorumlu saray görevlisi kimdir?', 'Mirahur', ['Doğancıbaşı', 'Müneccimbaşı', 'Çaşnigirbaşı'], 'Mirahur, saray ahırlarının (İstabl-ı Âmire) başındaki görevliydi; padişahın atları ve törenlerde at hazırlığı ona bağlıydı.'),
  ('Padişahın av kuşlarının bakımını yürüten saray görevlisi kimdir?', 'Doğancıbaşı', ['Mirahur', 'Hekimbaşı', 'Silahdar'], 'Doğancıbaşı, padişahın av kuşlarının (doğan, şahin) yetiştirilmesi ve bakımını yürüten görevlidir; av kültürünün saraydaki bir yansımasıdır.'),
  ('Saray için takvim hesabı ve uygun vakit tayini yapan görevli kimdir?', 'Müneccimbaşı', ['Hekimbaşı', 'Kilerci', 'Kapıcıbaşı'], 'Müneccimbaşı, saray astronomu ve takvim görevlisiydi; devlet işlerinde uygun vakit tespitinde de başvurulan bir makamdı.'),
  ('Padişaha imamlık eden saray din görevlisi kimdir?', 'Hünkâr imamı', ['Kayyum', 'Müezzinbaşı', 'Hatip'], 'Hünkâr imamı, padişaha imamlık eden ve onun dinî hizmetlerini yürüten saray din görevlisiydi; güvenilir ve itibarlı kişilerden seçilirdi.'),
  ('1914\'te Süleymaniye Külliyesi\'nin imaretinde açılan ve bugünkü Türk ve İslam Eserleri Müzesi\'nin öncüsü olan müze hangisidir?', 'Evkaf-ı İslamiye Müzesi', ['Müze-i Hümayun', 'Askerî Müze', 'Topkapı Sarayı Müzesi'], 'Evkaf-ı İslamiye Müzesi, vakıf eserlerini ve İslam sanat eserlerini toplamak amacıyla 1914\'te açılmış, sonradan Türk ve İslam Eserleri Müzesi olmuştur.'),
  ('Osmanlı hat sanatında Şeyh Hamdullah\'ın etkilendiği ve izinden gittiği Abbasi hattatı kimdir?', 'Yâkût el-Müsta\'sımî', ['İbn Mukle', 'İbnü\'l-Bevvâb', 'Hâfız Osman'], 'Şeyh Hamdullah, Yâkût el-Müsta\'sımî\'nin üslubunu Osmanlı\'ya aktarmış ve Osmanlı hat sanatının temelini oluşturmuştur.'),
  ('Osmanlı darüşşifasında gözünden rahatsız olan bir hasta, hangi uzman hekime başvururdu?', 'Kehhal', ['Cerrah', 'Mücebbir', 'Hekimbaşı'], 'Kehhal göz hastalıklarıyla ilgilenen hekimdi; cerrah ameliyat, mücebbir kırık-çıkık, hekimbaşı ise saray hekimlerinin başındaki görevliydi.'),
  ('Bir Osmanlı çarşısında ilaç yapımında kullanılan baharat ve bitki karışımlarını satan esnafa ne denirdi?', 'Aktar', ['Muhtesib', 'Kuyumcu', 'Saraç'], 'Aktar, ilaç niteliğindeki bitki, baharat ve ilaç hammaddelerini satan esnaftı; hekimlerin yazdığı karışımları da hazırlardı.'),
  ('Osmanlı darüşşifalarının vakıf gelirleriyle ücretsiz hizmet vermesi neyi gösterir?', 'Sağlık hizmetinin hayır ve sosyal yardım anlayışıyla sunulduğunu', ['Hastaların yalnızca askerlerden oluşup yalnızca savaş zamanında tedavi edildiğini', 'Tıp eğitiminin yasak olduğunu', 'Hekimlerin maaş almadığını'], 'Darüşşifalar vakıf geliriyle yoksul ve zenginlere ücretsiz bakım sunuyordu; bu sağlık hizmetinin sosyal yardım anlayışıyla yürütüldüğünü gösterir.'),
  ('Bir Osmanlı caminin avlusunda veya türbenin çevresinde bulunan mezarlık alanına ne ad verilir?', 'Hazire', ['Musalla', 'Şadırvan', 'Revak'], 'Hazire, türbe ya da cami çevresinde yer alan mezarlık alanıdır; hanedan üyeleri ve önemli kişiler burada gömülürdü.'),
  ('Bir Osmanlı camisinde müezzinlerin yüksek bir bölümde birlikte tekbir getirip namaza eşlik ettiği, çoğunlukla sütunlu yükseltilmiş bölüme ne denir?', 'Müezzin mahfili', ['Hünkâr mahfili', 'Son cemaat yeri', 'Kürsü'], 'Müezzin mahfili, müezzinlerin cemaatle birlikte namaza eşlik ettiği, yüksekçe ve çoğu zaman süslü bir bölümdür.'),
];
